window.__LEX={"G900":"<h1>bathuno</h1>\n<p>Strong n° 900 <i>Prononciation [bath-oo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la mer 'profonde', la haute mer</li>\n<li>profond, pauvreté extrême, les choses profondes de Dieu, cachées à l'homme, les conseils divins</li>\n<li>rendre profond, creuser profondément</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαθύνω</b> <span>(<i>f</i>. βαθυνῶ, <i>ao</i>. ἐϐάθυνα ; <i>pass. ao</i>. ἐϐαθύνθην ; <i>v. ci-dessous</i>)</span> <span>[ᾰ, ῡ <i>prés. et ao</i>., ῠ <i>fut</i>.]</span><br><b>   I <i>tr.</i></b> rendre profond, <i>d’où :</i><br><b>      1</b> creuser : χῶρον, IL. <i>23, 421,</i> un terrain, <i>en parl. d’un torrent ; au pass</i>. devenir <i>ou</i> être profond, <i>en parl. d’un lac,</i> TH. <i>H.P. 4, 11, 3 ; d’une blessure,</i> NONN. <i>D. 39, 305 ; p. suite,</i> être creux : χερσὶ βαθυνομέναις, NONN. <i>D. 11, 180,</i> dans le creux des mains ;<br><b>      2</b> étendre en profondeur : φάλαγγα, XÉN. <i>Cyr. 6, 3, 23, etc</i>. donner de la profondeur à une phalange, la former en colonne ;<br><b>   II <i>intr.</i></b> s’enfoncer, enfoncer, PHIL. <i>1, 248</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass. 3 pl</i>. βεϐάθυνται, STR. <i>902. Pl.q.pf. 3 sg. poét</i>. βεϐάθυστο, NONN. <i>D. 39, 305</i>.<br><span><b>Étym</b>. βαθύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαθυνω - βαθύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G901":"<h1>bathus</h1>\n<p>Strong n° 901 <i>Prononciation [bath-oos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>profond</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαθύς, εῖα, ύ</b> <span>[ᾰ]</span> profond, <i>d’où :</i><br><b>   I</b> <i>au pr. :</i><br><b>      1</b> profond, creux (<i>fossé,</i> IL. <i>7, 341 ; rivage,</i> IL. <i>2, 92 ; mer,</i> IL. <i>1, 532 ; coupe,</i> SOPH. <i>fr. 149 ; bergerie,</i> IL. <i>5, 142 ;</i> OD. <i>9, 239 ; gouffre,</i> IL. <i>8, 14, etc</i>.) ; βαθὺ πτῶμα, ESCHL. <i>Suppl. 796,</i> chute profonde, <i>càd</i>. d’un rocher élevé ;<br><b>      2</b> qui s’étend en profondeur, <i>càd</i>. sur un espace allongé (bois, forêt, IL. <i>5, 555, etc. ;</i> OD. <i>17, 316 ;</i> vallon, IL. <i>20, 490 ; etc</i>.) ; β. φάλαγξ, XÉN. <i>Lac. 11, 6,</i> ligne de bataille profonde ;<br><b>      3</b> qui s’étend en épaisseur, épais, profond : ἀὴρ β. vapeur épaisse, IL. <i>21, 7, ou</i> nuée épaisse, IL. <i>20, 446 ;</i> OD. <i>9, 144 ;</i> β. λαῖλαψ, IL. <i>11, 306,</i> épais tourbillon d’orage ; ἄμαθος β. IL. <i>5, 587,</i> sable épais <i>ou</i> profond ; γῆ β. EUR. <i>Andr. 637 ;</i> TH. <i>C.P. 1, 18,</i> terre épaisse, sol riche, <i>p. opp. à un sol pierreux ; d’où, avec idée d’abondance, de végétation luxuriante, de richesse, etc</i>. β. λήϊον, IL. <i>2, 147 ;</i> THGN. <i>107 ;</i> HDT. <i>5, 92, 6,</i> moisson abondante ; λειμὼν β. ESCHL. <i>Pr. 652,</i> prairie luxuriante ; τρίχες β. XÉN. <i>Cyn. 4, 8,</i> poils épais ; πώγων β. LUC. <i>Pisc. 41,</i> barbe touffue ; <i>fig</i>. β. πλοῦτος, EL. <i>V.H. 3, 18,</i> fortune opulente ; β. οἶκος, CALL. <i>Cer. 114,</i> maison riche ; β. ἀνήρ, XÉN. <i>Œc. 11, 10,</i> homme riche et puissant ; <i>en parl. de l’esprit ou du caractère :</i> φρὴν βαθεῖα, IL. <i>19, 125 ;</i> PD. ESCHL. <i>etc</i>. esprit profond, <i>càd</i>. grave, réfléchi (<i>p. opp. à</i> superficiel, léger, <i>etc</i>.) ; β. τῇ ψυχῇ, POL. <i>6, 24, 9,</i> qui a l’âme profonde, <i>càd</i>. qui sent <i>ou</i> pense fortement ; β. ἤθεα, HDT. <i>4, 95,</i> caractère profond, <i>càd</i>. grave, réfléchi ; <i>en mauv. part,</i> profond, <i>càd</i>. dissimulé, fourbe, MÉN. <i>fr. inc. 414 Meineke</i> (SUID.) ; <i>p. anal</i>. βαθὺ κλέος, PD. <i>O. 7, 53,</i> gloire profonde ; κίνδυνος β. PD. <i>P. 4, 207,</i> danger profond ; β. ὕπνος, THCR. <i>Idyl. 8, 65,</i> profond sommeil ;<br><b>      4</b> <i>en parl. de couleur (p. anal. avec l’ombre,</i> DC. <i>36, 32 ; avec un nuage,</i> DC. <i>50, 14 ; avec l’obscurité,</i> PHIL. <i>270</i> b) sombre, EL. <i>V.H. 6, 6 ;</i> NYSS. <i>3, 1081 a Migne ;</i><br><b>      5</b> <i>en parl. de la durée du temps,</i> qui est au fond, <i>càd</i>. à l’extrémité <i>ou</i> dans son plein : β. ὄρθρος, PLAT. <i>Crit. init. ;</i> AR. <i>Vesp. 216 ;</i> THCR. <i>Idyl. 18, 14,</i> point du jour extrême, <i>càd</i>. tout à fait le point du jour ; νὺξ β. LUC. <i>As. 34, 56,</i> pleine nuit ; τὸ βαθὺ τῆς ἡλικίας, AR. <i>Nub. 514,</i> le plein, <i>càd</i>. la force de l’âge.<br><span>•<i> Cp</i>. βαθύτερος, HDT. <i>4, 95 ;</i> XÉN. <i>Lac. 11, 6 ;</i> PLUT. <i>Eum. 16, etc.</i> <i>• Sup</i>. βαθύτατος, HDT. <i>5, 92 ;</i> DH. <i>Rhet. 282, 11 ; 365, 7 ; etc. — Cp. poét</i>. βαθίων <span>[ῑ]</span>, <i>d’où neutre</i> βάθιον <span>[ῐ]</span> THCR. <i>Idyl. 5, 43 ; par assimil</i>. βάσσον (= *βάθϳον, *βάθσον, βάσσον ; <i>cf</i>. κορύσσω, armer d’un casque = *κορύθϳω, *κορύθσω, κορύσσω) EPICH. <i>fr. 164 Ahrens</i>. <i>• Sup</i>. βάθιστος, IL. <i>8, 14</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém. épq</i>. βαθύς, HH. <i>Cer. 384 ;</i> CALL. <i>Del. 37 ; ou</i> βαθέη, IL. <i>5, 142, etc. ; épq. et ion</i>. βαθείη, IL. <i>2, 92, etc</i>.<br><span><b>Étym</b>. <i>cf</i>. βένθος, <i>d’où p.-ê. origine indo-europ. avec alternance</i> *-en-/-n̥-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαθυς - βαθύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G902":"<h1>baion</h1>\n<p>Strong n° 902 <i>Prononciation [bah-ee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une branche de palmier, une palme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαΐον, ου (τὸ) :<br>      1</b> feuille de palmier, SPT. <i>1Macc. 13, 51 ;</i><br><b>      2</b> <i>au plur</i>. branche de palmier, <i>et p. ext</i>. de myrte, d’olivier, de laurier, NT. <i>Joh. 12, 13 ;</i> ECCL.<br><span><b>Étym</b>. βάϊς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαιον - βαΐον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G903":"<h1>Balaam</h1>\n<p>Strong n° 903 <i>Prononciation [bal-ah-am']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Balaam = « qui détruit le temple », « qui avale »\n<ol><li>devin, fils de Béor, il habitait la ville de Pethor sur l'Euphrate en Aram (Mésopotamie). Balak, roi de Moab, lui envoya des anciens de Moab et de Madian qui lui offrirent une grande récompense, à condition qu'il maudisse les Israélites. L'Eternel l'obligea en réalité à bénir le peuple qui devait être maudit. Balaam demeure le type du faux prophète, ami de l'argent et des honneurs, dont l'attitude douteuse conduit au relâchement de l'enseignement et de la conduite.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαλααμ</font> &lt; בלעם - <font face=\"Georgia\">Βαλαάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G904":"<h1>Balak</h1>\n<p>Strong n° 904 <i>Prononciation [bal-ak']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Balak = « qui dévaste », « qui gaspille »\n<ol><li>un roi de Moab</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαλακ</font> &lt; בלק - <font face=\"Georgia\">Βαλάκ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G905":"<h1>balantion</h1>\n<p>Strong n° 905 <i>Prononciation [bal-an'-tee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un porte-monnaie, une bourse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαλλάντιον</b>, <i>v</i>. βαλάντιον.<br>\n<b>βαλάντιον, ου (τὸ)</b> <span>[βᾰ]</span><br><b>      1</b> bourse, AR. <i>Av. 157, etc. ;</i> XÉN. PLAT. <i>etc</i>. ANTH. <i>5, 159</i> (βαλλαντ-) ;<br><b>      2</b> javelot, DIONYS. (ATH. <i>98</i> b).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαλαντιον - βαλλάντιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (4)</li>\n</ul>\n</td></tr>\n</table>","G906":"<h1>ballo</h1>\n<p>Strong n° 906 <i>Prononciation [bal'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter ou laisser tomber une chose sans se préoccuper de l'endroit de la chute\n<ol type=\"a\">\n<li>éparpiller, jeter</li>\n<li>donner sans être certain du résultat</li>\n<li>pour les liquides\n<ol>\n<li>verser, couler comme un fleuve</li>\n<li>déborder</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>remplir, insérer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάλλω</b> <span>(<i>impf</i>. ἔϐαλλον, <i>f</i>. βαλῶ, <i>ao.2</i> ἔϐαλον, <i>pf</i>. βέϐληκα, <i>pl.q.pf</i>. ἐϐεϐλήκη <i>ou</i> ἐϐεϐλήκειν ; <i>pass. f</i>. βληθήσομαι, <i>ao</i>. ἐϐλήθην, <i>pf</i>. βέϐλημαι)</span><br><b>A</b> lancer, jeter, <i>d’où :</i><br><b>   I <i>tr</i>.<br>      1</b> lancer : βέλος, λίθον, <i>etc</i>. HOM. (OD. <i>9, 495, etc.) etc</i>. un trait, une pierre ; εὐνάς, OD. <i>9, 137,</i> jeter l’ancre ; τι εἰς ἅλα, IL. <i>1, 314,</i> jeter qqe ch. dans la mer, <i>ou avec</i> ἐν <i>et le dat</i>. τι ἐν πυρί, OD. <i>14, 429,</i> qqe ch. dans le feu ; χαλκὸν ἐν στήθεσσιν, IL. <i>5, 346 (cf</i>. OD. <i>20, 62</i>), un fer dans la poitrine ; πῦρ ἐν νηυσίν, IL. <i>13, 629,</i> du feu sur les vaisseaux ; τι ποτὶ πέτρας, OD. <i>12, 71,</i> qqe ch. contre des rochers, <i>ou avec</i> πρός (προτί) <i>et le dat</i>. σκῆπτρον προτὶ γαίῃ, IL. <i>1, 245,</i> jeter son bâton contre terre ; <i>fig</i>. ὕπνον ἐπὶ βλεφάροις, OD. <i>1, 364,</i> jeter le sommeil sur les paupières ; λύπην τινί, SOPH. <i>Ph. 67,</i> jeter le chagrin dans l’âme de qqn ; ἐν στήθεσσι μένος β. τινί, IL. <i>5, 513,</i> jeter le courage dans l’âme de qqn ; τί τινι ἐν θυμῷ, OD. <i>1, 201, etc. ou</i> ἐν καρδίᾳ, PD. <i>O. 13, 16, ou</i> θυμῷ, ESCHL. <i>Pr. 705, ou</i> ἐς θυμόν, SOPH. <i>O.R. 975,</i> jeter qqe ch. (un sentiment de colère, de crainte, <i>etc</i>.) dans le cœur (de qqn) ; <i>fig. avec rég. de pers</i>. β. τινὰ ἐς κακόν, OD. <i>12, 221,</i> précipiter qqn dans le malheur ; τινὰ ἐς φόϐον, EUR. <i>Tr. 1058,</i> jeter qqn en crainte ; <i>p. anal</i>. κινδύνῳ β. χώραν, ESCHL. <i>Sept. 1048,</i> mettre un pays en péril ;<br><b>      2</b> jeter à terre, renverser : τινὰ ἐν δαπέδῳ, OD. <i>22, 188,</i> qqn sur le sol ; ἐν κονίῃσιν, IL. <i>8, 156,</i> qqn dans la poussière ; οἶκον, ESCHL. <i>Eum. 721,</i> renverser, <i>d’où</i> détruire une maison ;<br><b>      3</b> lancer, faire tomber : κύϐους, ESCHL. EUR. PLAT. lancer des dés ; ἑτέρωσε β. ὄμματα, OD. <i>16, 179,</i> jeter ses regards dans une autre direction ; ὄμμα πρὸς γῆν, EUR. <i>Ion 582,</i> baisser les yeux vers la terre ; ἴχνος ποδὸς ἐπὶ γᾶν, EUR. <i>Rhes. 721,</i> imprimer la trace de ses pas sur le sol ; <i>d’où</i> poser sur <i>ou</i> dans : ἄστυ β. A. RH. <i>2, 849,</i> jeter les fondements d’une ville ; β. χεῖρας ἀμφί τινι, OD. <i>7, 142,</i> jeter ses bras autour de qqe ch. (les genoux de qqn, <i>etc</i>.) ; ἀμφί τινι β. πήχεε, OD. <i>17, 38 ; 24, 346, ou abs</i>. ἀμφὶ δὲ χεῖρας β. OD. <i>4, 455,</i> jeter ses bras autour de qqn, embrasser qqn ; <i>avec deux dat</i>. ἀμφὶ δὲ χεῖρας δειρῇ β. τινι, OD. <i>23, 207,</i> jeter ses bras autour du cou de qqn ; μῆλα ἐν νηΐ, OD. <i>9, 470,</i> embarquer des troupeaux ; κύκλα β. ἀμφὶ ὀχέεσσι, IL. <i>5, 722,</i> poser des roues des deux côtés des chars ; <i>part. en parl. d’armes, de vêtements, etc</i>. β. ἀμφ' ὤμοις αἰγίδα, IL. <i>18, 204,</i> jeter, <i>càd</i>. placer vivement son bouclier autour des épaules (d’Achille), <i>en parl. d’Athènè ;</i> ἀμφί τινι ῥάκος, OD. <i>14, 342,</i> jeter des haillons sur le corps de qqn ; <i>abs</i>. mettre le feu (à une ville, à une maison) POL. <i>1, 48, 8 (cf</i>. πῦρ ἐμϐαλεῖν, POL. <i>5, 100, 5</i>) ;<br><b>      4</b> laisser tomber : δάκρυ, OD. <i>4, 198,</i> une larme ; ἑτέρωσε κάρη β. IL. <i>8, 306,</i> laisser tomber sa tête de l’autre côté ; β. τοὺς ὀδόντας, ARSTT. <i>H.A. 6, 20, 11, ou abs</i>. βάλλειν, ARSTT. <i>H.A. 6, 22, 6,</i> perdre ses dents ;<br><b>      5</b> jeter de côté, rejeter : τινὰ γῆς ἔξω, SOPH. <i>O.R. 622,</i> jeter qqn hors de son pays, le bannir ; β. ἄθαπτόν τινα, SOPH. <i>Aj. 1333,</i> refuser la sépulture à qqn ;<br><b>   II <i>intr.</i></b> <i>en apparence</i> (<i>s.-e</i>. ἑαυτόν) se jeter : εἰς ἅλα, IL. <i>11, 722,</i> dans la mer, <i>en parl. d’un fleuve ;</i> περὶ τέρμα, IL. <i>23, 462,</i> s’élancer autour du but, <i>en parl. de chevaux ;</i> ἐν πέδῳ, ESCHL. <i>Ag. 1172,</i> être précipité sur le sol ; βάλλ' ἐς κόρακας, AR. <i>Vesp. 835, etc. ou</i> ἐς μακαρίαν, PLAT. <i>Hipp. ma. 293</i> a, va te jeter en pâture aux corbeaux <i>ou</i> va te jeter dans le séjour des bienheureux, <i>càd</i>. va au diable ! va te faire pendre ! <i>etc. ; abs</i>. βαλὼν κάθευδε, ARR. <i>Epict. 2, 20, 10,</i> étends-toi et dors ;<br><b>B</b> frapper à distance (d’un trait, d’une pierre, <i>etc</i>.) : β. τινά, IL. <i>11, 350 ;</i> OD. <i>7, 64, etc</i>. frapper qqn d’un trait ; <i>avec double rég</i>. τινὰ δουρί, IL. <i>11, 742,</i> frapper qqn d’une lance ; σάκος λίθῳ, IL. <i>7, 266,</i> frapper un bouclier d’une pierre ; <i>en outre, avec un dat. instrum</i>. τινὰ μηρὸν ὀϊστῷ, IL. <i>11, 583,</i> frapper qqn d’un trait à la cuisse ; <i>ou simpl. sans dat. instrum. mais avec un double rég. de la pers. ou de la chose frappée et de la partie atteinte :</i> τινὰ στῆθος, IL. <i>4, 480,</i> frapper qqn à la poitrine ; <i>de même</i> βάλλειν τινὰ κατά τι, IL. <i>5, 66, etc. ;</i> τινὰ πρός τι, IL. <i>11, 144 ; 15, 249 ;</i> τινὰ ὑπό τι, IL. <i>17, 309 ; rar. avec le gén. de pers</i>. β. τινὸς κατά τι, IL. <i>5, 305,</i> frapper qqn en qqe partie du corps <i>ou</i> de son armure ; <i>avec l’acc. de la blessure :</i> ἕλκος τό μιν βάλε Πάνδαρος ἰῷ, IL. <i>5, 795,</i> la blessure que lui fit Pandaros en le frappant d’un trait ; <i>fig</i>. β. τινὰ κακοῖς, SOPH. <i>Aj. 1244,</i> frapper qqn de malheurs ; φθόνῳ, EUR. <i>El. 902,</i> poursuivre qqn de sa haine ; <i>au pass</i>. ἄχεϊ <i>ou</i> πένθεϊ βεϐολημένος ἦτορ, IL. <i>9, 9, ou</i> κῆρ, OD. <i>10, 245,</i> frappé de douleur dans son cœur ; <i>avec un sujet de chose :</i> β. τινά, IL. <i>11, 536 ; 23, 502, etc</i>. atteindre qqn, <i>en parl. de gouttes de sang, de flots de poussière, etc. ; en parl. du soleil :</i> ἀκτῖσιν βάλλειν, OD. <i>5, 479,</i> frapper de ses rayons ; <i>p. anal</i>. κτύπος οὔατα βάλλει, IL. <i>10, 535 (cf</i>. SOPH. <i>Ant. 1188 ; Ph. 205</i>) un bruit frappe les oreilles ; <i>de même en parl. d’odeurs,</i> SOPH. <i>fr. 411 ; p. ext</i>. avoir une portée de, <i>en parl. de machines de jet :</i> ὁ καταπέλτης ἔϐαλλε τρία στάδια καὶ ἡμιστάδιον, ATHÉNÉE MÉC. <i>8, 7,</i> la catapulte portait à 3 stades ½ ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. βαλοῦμαι, <i>ao.2</i> ἐϐαλόμην)</span><br><b>      1</b> jeter sur soi <i>ou</i> qqe ch. à soi : ἀμφὶ ὤμοισιν ξίφος, IL. <i>3, 334, ou</i> τόξα, IL. <i>19, 372,</i> se jeter autour des épaules (le baudrier qui supporte) une épée, un carquois ; χρόα λουτροῖς, HH. <i>Cer. 50, litt</i>. jeter son corps dans le bain, se jeter au bain ; <i>fig</i>. τι ἐπὶ θυμῷ βάλλεσθαι, IL. <i>15, 566 ; 20, 196, ou</i> ἐνὶ φρεσί, IL. <i>1, 297 ;</i> OD. <i>11, 454 ;</i> HÉS. <i>O. 107 ; ou</i> μετὰ φρεσί, IL. <i>9, 435 ; ou</i> ἐς θυμόν, HDT. <i>1, 84,</i> se mettre qqe ch. dans l’esprit ; ἐπ' ἑωυτοῦ βαλόμενος, HDT. <i>3, 71, 155, etc</i>. s’étant mis de lui-même (qqe ch.) dans l’esprit, ayant décidé d’après son propre jugement ;<br><b>      2</b> jeter pour soi, pour son usage : β. ἄγκυραν, HDT. <i>9, 74,</i> jeter l’ancre ; κρηπῖδα, PD. <i>I. 5, 11,</i> jeter des fondations, les fondements (de qqe ch.) ; <i>en parl. de campements, de fortifications, etc</i>. DÉM. POL. <i>etc.,</i> φόνον β. τινί, Q. SM. donner (<i>litt</i>. lancer) la mort à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. Prés. 1 pl. dor</i>. βάλλομες, BION <i>7, 13. Impf. épq. sans augm</i>. βάλλον, IL. <i>18, 534. Fut. épq. et ion</i>. βαλέω <span>[ᾰ]</span> IL. <i>8, 403 ; 3 sg</i>. βαλέει, OD. <i>10, 290 ;</i> HH. <i>Ven. 288 ; inf</i>. βαλέειν, IL. <i>8, 417, mais</i> βαλεῖν, HH. <i>Merc. 374 ; part</i>. βαλέων, OD. <i>11, 608. Autre fut</i>. βαλλήσω, AR. <i>Vesp. 222, 1491. Ao.2 poét. sans augm</i>. βάλον, IL. <i>11, 742 ;</i> HÉS. <i>Sc. 384 ; sbj. 2 sg. épq</i>. βάλῃσθα, OD. <i>12, 221 ; 3 sg. épq</i>. βάλῃσι, IL. <i>21, 104, 576 ; opt. 2 sg. épq</i>. βάλοισθα, IL. <i>15, 571 ; part. fém. dor</i>. βαλοῖσα, THCR. <i>Idyl. 16, 11. Pl.q.pf. sans augm. 3 sg</i>. βεϐλήκει, IL. <i>5, 661. — Pass. ao.2 épq</i>. ἐϐλήμην, <i>d’où 3 sg</i>. ἔϐλητο <i>et</i> βλῆτο, IL. <i>11, 675, etc. ; sbj. 3 sg</i>. βλήεται (<i>p</i>. *βλήηται) OD. <i>17, 472 ; opt. 2 sg</i>. βλῇο (<i>var</i>. βλεῖο) IL. <i>13, 288 ; inf</i>. βλῆσθαι, IL. <i>4, 115 ; part</i>. βλήμενος, IL. <i>11, 191 ;</i> OD. <i>22, 18 ;</i> A. RH. <i>2, 1212. Pf. 2 sg. poét</i>. βέϐληαι, IL. <i>5, 284 ; 11, 380</i> <span>[<i>l’</i>η <i>compte pour une brève</i>]</span> ; <i>13, 251 ; 3 pl. épq</i>. βεϐλήαται (pour βέϐληνται) IL. <i>11, 657 ;</i> OD. <i>11, 194 ; de ce pf. vient le pl.q.pf. poét. sans augm. 3 sg</i>. βέϐλητο, OD. <i>12, 423 ; 3 pl. ion</i>. βεϐλήατο (<i>p</i>. ἐϐέϐληντο) IL. <i>14, 28. Autre pf. épq</i>. *βεϐόλημαι, <i>d’où 2 sg</i>. βεϐόλησαι, A. RH. <i>4, 1318 ; 3 sg</i>. βεϐόληται, A. RH. <i>3, 893 ; part</i>. βεϐολημένος, IL. <i>9, 9 ;</i> OD. <i>10, 247 ;</i> A. RH. <i>1, 262 ; etc. ; de ce pf. vient le pl.q.pf. 3 pl. poét</i>. βεϐολήατο, IL. <i>9, 3. Fut. ant</i>. βεϐλήσομαι, EUR. <i>Or. 271 ; Bacch. 1314 ; part</i>. βεϐλησόμενος, PHILSTR. <i>V. Ap. 251. — Moy. prés. 2 sg. épq</i>. βάλλεαι, IL. <i>9, 435 ; impér. poét. 2 sg</i>. βάλλεο, IL. <i>4, 39, ion</i>. βάλλευ, OD. <i>12, 218. Impf. poét</i>. βαλλόμην, PD. <i>P. 4, 138. Impf. itér. 3 sg. ion</i>. βαλλέσκετο, HDT. <i>9, 74. Ao.2 poét</i>. βαλόμην, IL. <i>11, 29 ;</i> PD. <i>P. 1, 74 ; impér. ion. 2 sg</i>. βαλεῦ, THGN. <i>1050 ;</i> HDT. <i>8, 68</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>elh₁-, atteindre en lançant ; βάλλω <i>du proto-grec</i> *g<sup>w</sup>al-je/o- <i>ou</i> *g<sup>w</sup>al-n-e/o-, <i>p.-ê. de</i> *g<sup>w</sup>l̥-n(e)h₁-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαλλω - βάλλω</font>\n<br><br>mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n125 fois dans 107 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (36)</li>\n<li>Marc (20)</li>\n<li>Luc (18)</li>\n<li>Jean (17)</li>\n<li>Actes (5)</li>\n<li>Jacques (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (27)</li>\n</ul>\n</td></tr>\n</table>","G907":"<h1>baptizo</h1>\n<p>Strong n° 907 <i>Prononciation [bap-tid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plonger, immerger, submerger (d'un navire coulé)</li>\n<li>purifier en plongeant ou submergeant, laver, rendre pur avec beaucoup d'eau, se laver, se baigner</li>\n<li>accabler</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαπτίζω</b> <span>(<i>f</i>. ίσω, <i>att</i>. -ιῶ)</span><br><b>      1</b> plonger, immerger <i>ou</i> submerger : ἑαυτὸν εἰς θάλασσαν, PLUT. <i>M. 166</i> a, se plonger dans la mer ; <i>ou</i> τινὰ πρὸς θάλασσαν, PLUT. <i>M. 914,</i> plonger qqn dans la mer ; <i>en parl. de navires,</i> submerger un navire, le mettre hors de service, POL. <i>1, 51, 6, etc. ; fig</i>. β. τινὰ ὕπνῳ, ANTH. <i>11, 49,</i> plonger qqn dans le sommeil ; <i>au pass</i>. être immergé <i>ou</i> submergé, HPC. <i>etc. ; fig</i>. ὀφλήμασι βεϐαπτισμένος, PLUT. <i>Galb. 21,</i> couvert (<i>litt</i>. submergé) de dettes ; <i>abs</i>. βεϐαπτισμένοι, PLAT. <i>Conv. 176</i> b, plongés dans l’ivresse ; βαπτιζόμενος, PLAT. <i>Euthyd. 277</i> d, qui se noie, qui s’enfonce dans l’eau, qui perd pied, <i>en parl. d’une personne troublée par des sophismes ou des questions embarrassantes ;</i><br><b>      2</b> plonger (un vase) pour puiser, <i>d’où</i> puiser : φιάλαις β. ἐκ κρατήρων, PLUT. <i>Alex. 67,</i> puiser avec des tasses dans des cratères ;<br><b>      3</b> baptiser (<i>à l’origine,</i> avec immersion) <i>acc</i>. NT. <i>Marc. 1, 4 ; au pass</i>. être baptisé, NT. <i>Matth. 3, 11, etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> se plonger (dans l’eau) SPT. <i>4Reg. 5, 14 ;</i><br><b>      2</b> se faire baptiser, NT. <i>Ap. 22, 26, etc</i>.<br><span><b>Étym</b>. βάπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαπτιζω - βαπτίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n77 fois dans 63 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (12)</li>\n<li>Luc (10)</li>\n<li>Jean (13)</li>\n<li>Actes (21)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (11)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G908":"<h1>baptisma</h1>\n<p>Strong n° 908 <i>Prononciation [bap'-tis-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>baptême Chrétien : rite d'immersion dans l'eau comme l'a commandé Christ, par ceux qui ont confessé leurs péchés et professé leur foi en Christ, sont nés de nouveau à une nouvelle vie par l'action du saint Esprit, devenant publiquement membres du corps de Christ et de l'Eglise.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάπτισμα, ατος (τὸ) :<br>      1</b> baptême, NT. ECCL. ;<br><b>      2</b> supplice de l’immersion, <i>qqf. appliqué aux martyrs,</i> NAZ. <i>2, 236 b Migne</i>.<br><span><b>Étym</b>. βαπτίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαπτισμα - βάπτισμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n20 fois dans 20 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (4)</li>\n<li>Luc (4)</li>\n<li>Actes (6)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G909":"<h1>baptismos</h1>\n<p>Strong n° 909 <i>Prononciation [bap-tis-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lavage ou purification effectuée au moyen de l'eau\n<ol type=\"a\">\n<li>lavage prescrit par la loi Mosaïque Hé 9:10 qui semble indiquer la différence avec le baptême chrétien</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαπτισμός, οῦ (ὁ)</b> immersion, <i>d’où :</i><br><b>      1</b> ablution, NT. <i>Marc. 7, 4, 8 ; Hebr. 9, 10 ;</i><br><b>      2</b> baptême, JOS. <i>A.J. 18, 5, 2</i>.<br><span><b>Étym</b>. βαπτίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαπτισμος - βαπτισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)/li>\n<li>Hébreux (2)-</li>\n</ul>\n</td></tr>\n</table>","G910":"<h1>Baptistes</h1>\n<p>Strong n° 910 <i>Prononciation [bap-tis-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui baptise, baptiseur</li>\n<li>celui qui administre le rite du baptême</li>\n<li>le surnom de Jean, l'avant-coureur de Christ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαπτιστής, οῦ (ὁ)</b> celui qui immerge, qui baptise, NAZ. ; <i>2, 252</i> c ; <i>393</i> c <i>Migne ;</i> Ἰωάννης ὁ Β. NT. JOS. <i>A.J. 18, 5, 2,</i> Jean Baptiste, <i>litt</i>. Jean l’immerseur.<br><span><b>Étym</b>. βαπτίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαπτιστης - βαπτιστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (3)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G911":"<h1>bapto</h1>\n<p>Strong n° 911 <i>Prononciation [bap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plonger, tremper, immerger</li>\n<li>plonger dans la mort, teindre, colorer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάπτω</b> <span>(<i>f</i>. βάψω, <i>ao</i>. ἔϐαψα, <i>pf. inus. ; pass. ao.2</i> ἐϐάφην <span>[ᾰ]</span>, <i>pf</i>. βέϐαμμαι)</span><br><b>   I <i>tr.</i></b> plonger, immerger : εἰν ὕδατι, OD. <i>9, 392 ;</i> ἐν ὕδατι, HPC. <i>468, 50 ;</i> ὕδατι, HPC. <i>553, 31 ;</i> εἰς ὕδωρ, PLAT. <i>Tim. 73</i> e, dans l’eau ; <i>p. anal</i>. φάσγανον εἴσω σαρκὸς β. EUR. <i>Ph. 1577,</i> plonger un glaive dans la chair (de qqn) ; εἰς τὰς πλευρὰς β. τὴν αἰχμήν, DH. <i>5, 15,</i> plonger sa lance dans les flancs (de qqn) ; <i>d’où</i> ἐν σφαγαῖσι β. ξίφος, ESCHL. <i>Pr. 863,</i> plonger une épée dans le corps d’un homme et le tuer ; β. ἔγχος πρὸς Ἀργείων στρατῷ, SOPH. <i>Aj. 95,</i> plonger son épée dans les rangs de l’armée argienne ; <i>part. :</i><br><b>      1</b> plonger (du fer, de l’acier) dans l’eau, <i>d’où</i> tremper (du fer, de l’acier) OD. <i>9, 392 (v. ci-dessus</i>) ; PLUT. <i>M. 136</i> a ;<br><b>      2</b> plonger dans la teinture, <i>d’où</i> teindre, BATR. <i>220 ;</i> HDT. <i>7, 67 ;</i> PLAT. <i>Rsp. 429</i> d ; <i>ou</i> enduire d’une teinture : τρίχας β. ANTH. <i>11, 68,</i> teindre des cheveux (<i>cf. le Moy</i>.) ; enduire d’un poison, <i>en parl. de traits, etc</i>. SOPH. <i>Tr. 574 ;</i><br><b>      3</b> plonger dans l’eau, <i>d’où</i> baigner, laver, AR. <i>Eccl. 216 ;</i><br><b>      4</b> plonger pour puiser, <i>d’où</i> puiser : β. ποντίας ἁλός, EUR. <i>Hec. 610,</i> plonger (un vase pour puiser de l’eau) dans la mer ; <i>cf</i>. THCR. <i>Idyl. 5, 127, etc. ;</i><br><b>   II <i>intr.</i></b> se plonger, s’enfoncer dans l’eau, <i>en parl. d’un navire,</i> EUR. <i>Or. 707 ;</i> εἰς ψυχρόν, ARSTT. <i>H.A. 8, 2, 37,</i> plonger dans l’eau froide ; β. κῦμα, BABR. <i>71, 2,</i> s’enfoncer dans les flots, <i>en parl. d’un navire ; ou</i> β. ῥόου, ARAT. <i>858,</i> se plonger dans le courant <i>càd</i>. fendre les flots ;<br><b><i>Moy.</i></b> :<br><b>      1</b> faire teindre, AR. <i>Lys. 51 ;</i><br><b>      2</b> se teindre les cheveux, MÉN. <i>4, 178 Meineke</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. fut.2</i> βαφήσομαι, SPT. <i>Lev. 41, 32 ;</i> M. ANT. <i>8, 51. Ao.1</i> ἐϐάφθην, ANTH. <i>6, 254</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαπτω - βάπτω</font>\n<nbr>un mot primaire TDNT – : , </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G912":"<h1>Barabbas</h1>\n<p>Strong n° 912 <i>Prononciation [bar-ab-bas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Barabbas = « fils d'un père »\n<ol><li>le malfaiteur que les Juifs demandèrent à Pilate de relâcher à la place de Christ</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βαραϐϐᾶς, ᾶ (ὁ)</b> Barabbas, <i>n. d’h. hébr</i>. NT. NONN.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαραββας</font> &lt; בר־אבא - <font face=\"Georgia\">Βαραββᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G913":"<h1>Barak</h1>\n<p>Strong n° 913 <i>Prononciation [bar-ak']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Barak = « éclairs, foudre »\n<ol><li>un chef chez les Israélites, juge israélite</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βαράκ (ὁ)</b> Barak, <i>autre forme du n</i>. Βαραχίας, NT. <i>Hebr. 11, 32</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαρακ</font> &lt; ברק - <font face=\"Georgia\">Βαράκ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G914":"<h1>Barachias</h1>\n<p>Strong n° 914 <i>Prononciation [bar-akh-ee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Barachie (Angl. Barachiah) = « l'Eternel a béni »\n<ol><li>il est dit qu'il était le père du Zacharie tué dans le temple</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βαραχίας (ὁ)</b> Barakhias, <i>n. d’h. hébr</i>. NT. <i>Matth. 23, 35</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαραχιας</font> &lt; ברכיה - <font face=\"Georgia\">Βαραχίας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G915":"<h1>barbaros</h1>\n<p>Strong n° 915 <i>Prononciation [bar'-bar-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui dont le parler est rude, grossier</li>\n<li>celui qui parle une langue étrangère ou un langage non compris par un autre</li>\n<li>utilisé par les Grecs pour tous les étrangers ignorant la langue Grecque, avec une notion complémentaire de rudesse et de brutalité. Le mot est utilisé dans le N.T avec une idée de reproches.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάρϐαρος, ος, ον</b> <span>[ᾰρο]</span><br><b>   I</b> étranger, barbare, <i>càd</i>. non grec, <i>p. opp. à</i> Ἕλλην, THC. <i>1, 3 ;</i> PLAT. <i>Pol. 262</i> d ; EUR. <i>I.A. 1400 ;</i> ARSTT. <i>Pol. 3, 14, 6, etc. ;</i> ἡ βάρϐαρος (<i>s.-e</i>. γῆ) THC. <i>2, 97 ;</i> XÉN. <i>An. 5, 5, 16,</i> les pays étrangers, <i>càd</i>. non helléniques ; <i>même dans la bouche d’étrangers parlant de leur pays, p. opp. à la Grèce (p. ex. dans la bouche d’Atossa, parlant de l’Asie</i>), ESCHL. <i>Pers. 187 ;</i> τὸ βάρϐαρον, DH. les étrangers, l’étranger ; οἱ βάρϐαροι, les étrangers, <i>p. opp. aux Grecs, particul. les Mèdes et les Perses,</i> ESCHL. <i>Pers. 255, 337, etc</i>. HDT. XÉN. <i>etc. ;</i> β. φωνή, ESCHL. <i>Ag. 1051 ;</i> PLAT. <i>Prot. 341</i> c ; γλῶσσα β. SOPH. <i>Aj. 1263,</i> langue étrangère <i>ou</i> barbare ; <i>p. anal. en parl. des oiseaux,</i> dont le chant est inintelligible, AR. <i>Av. 199 ;</i><br><b>   II</b> <i>p. suite,</i> qui concerne les étrangers <i>ou</i> barbares : βάρϐαρος πόλεμος, THC. <i>2, 36,</i> guerre étrangère, avec les barbares ;<br><b>   III</b> semblable au langage <i>ou</i> aux mœurs des barbares, <i>d’où :</i><br><b>      1</b> barbare, incorrect, <i>en parl. des fautes contre le bon usage de la langue grecque,</i> LUC. <i>Sol. 5 ;</i><br><b>      2</b> grossier, non civilisé, AR. <i>Nub. 492 ;</i> DÉM. <i>563, 13 ;</i><br><b>      3</b> cruel, ANTH. <i>5, 2</i>.<br><span>•<i> Cp</i>. βαρϐαρώτερος, X. ÉPH. <i>p. 35, éd. Loc. Sup</i>. βαρϐαρώτατος, THC. <i>8, 98 ;</i> XÉN. <i>An. 5, 4, 34 ;</i> AR. <i>Av. 1573 ;</i> DS. <i>14, 30</i>.<br><span><b>Étym</b>. <i>mot onomatopéique avec redoubl., cf. lat</i>. balbus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαρβαρος - βάρβαρος</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G916":"<h1>bareo</h1>\n<p>Strong n° 916 <i>Prononciation [bar-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>porter un fardeau, supporter un poids, accablé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαρέω-ῶ</b> <span>(<i>impf</i>. ἐϐάρουν, <i>f</i>. βαρήσω, <i>ao</i>. ἐϐάρησα, <i>pf</i>. βεϐάρηκα ; <i>pass. ao</i>. ἐϐαρήθην, <i>pf</i>. βεϐάρημαι)</span> <span>[ᾰ]</span><br><b>   I <i>tr</i>.<br>      1</b> charger d’un poids lourd, alourdir, <i>acc</i>. LUC. <i>D. mort. 10, 4 ; au pass</i>. être alourdi (<i>par l’ivresse,</i> PLAT. <i>Conv. 203</i> b ; <i>par le sommeil, avec</i> ὕπνῳ, NT. <i>Luc. 9, 32 ; ou absol</i>. NT. <i>Marc. 14, 40 ; Matth. 26, 43) ; fig</i>. accabler (<i>d’impôts,</i> JOS. <i>B.J. 2, 14, 1 ; de douleur,</i> THCR. <i>Idyl. 17, 61</i>) ;<br><b>      2</b> <i>p. suite,</i> peser (de haut en bas) sur, <i>acc</i>. HÉRON <i>Aut. 266 ;</i> JOS. <i>A.J. 15, 3, 3 ;</i><br><b>   II</b> <i>intr. (au part. pf. épq</i>. βεϐαρηώς) être alourdi (par le vin), OD. <i>3, 139 ; 19, 122</i>.<br><span><b>Étym</b>. βάρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαρεω - βαρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Livre</li>\n</ul>\n</td></tr>\n</table>","G917":"<h1>bareos</h1>\n<p>Strong n° 917 <i>Prononciation [bar-eh'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lourdement, tristement, avec difficulté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαρέως</b> <span>[ᾰ]</span> <i>adv</i>., pesamment, <i>d’où :</i><br><b>      1</b> fortement, vigoureusement, HÉRON <i>Aut. 270 ;</i><br><b>      2</b> péniblement, avec peine : β. φέρειν τι, HDT. <i>5, 19 ;</i> XÉN. <i>Cyr. 2, 2, 1, etc. ;</i> AR. <i>Eccl. 174, etc. ; ou</i> τινι, EUR. <i>Her. arg. ; ou</i> ἐπί τινι, POL. <i>15, 1, 1 ; ou</i> ὑπέρ τινος, SPT. <i>2Macc. 14, 27,</i> supporter qqe ch. avec peine ; β. ἔχειν πρός τι, ARSTT. <i>Pol. 5, 10,</i> être mal disposé pour qqe ch. ; β. ἀκούειν, XÉN. <i>An. 2, 1, 9,</i> écouter avec ennui ;<br><b>      3</b> <i>t. de gr</i>. avec accent grave, ARSTT. <i>Soph. el. 21 ;</i> ATH. <i>53</i> b ; DYSC. <i>Pron. 364</i> b.<br><span>•<i> Cp</i>. βαρυτέρως, SPT. <i>3Macc. 3, 1</i>. <i>• Sup</i>. βαρύτατα, HPC. <i>112, 3 ;</i> PLAT. <i>Crit. 43</i> c ; EL. <i>V.H. 2, 12</i> a.<br><span><b>Étym</b>. βαρύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαρεως - βαρέως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G918":"<h1>Bartholomaios</h1>\n<p>Strong n° 918 <i>Prononciation [bar-thol-om-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Barthélemy (Angl. Bartholomew) = « fils de Tolmaï »\n<ol><li>un des douze apôtres de Christ, probablement surnom de Nathanaël (Don de Dieu)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βαρθολομαῖος, ου (ὁ)</b> Bartholomée, <i>n. d’h. hébr</i>. NT.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαρθολομαιος</font> &lt; בר־תלמי - <font face=\"Georgia\">Βαρθολομαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G919":"<h1>Bariesous</h1>\n<p>Strong n° 919 <i>Prononciation [bar-ee-ay-sooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bar-Jésus (Angl. Barjesus) = « fils de Jésus »\n<ol><li>un certain faux prophète</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαριησους</font> &lt; בר־ישוע - <font face=\"Georgia\">Βαριησοῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G920":"<h1>Barionas</h1>\n<p>Strong n° 920 <i>Prononciation [bar-ee-oo-nas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Fils de Jonas (Angl. Barjona) = « fils de Jonas »\n<ol><li>le surnom de l'apôtre Pierre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαριωνας</font> &lt; בר־יונה - <font face=\"Georgia\">Βαριωνᾶ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G921":"<h1>Barnabas</h1>\n<p>Strong n° 921 <i>Prononciation [bar-nab'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Barnabas = « fils de la prophétie »\n<ol><li>surnom de Joses ou Joseph, Lévite, natif de Chypre, enseignant chrétien distingué, compagnon et collègue de Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βαρναϐᾶς, ᾶ (ὁ)</b> Barnabas, <i>n. d’h. hébreu,</i> NT.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαρναβας</font> &lt; בר־נבא - <font face=\"Georgia\">Βαρναβᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 28 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (24)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (3)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G922":"<h1>baros</h1>\n<p>Strong n° 922 <i>Prononciation [bar'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lourdeur, accablement, poids, fardeau, difficulté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάρος, εος-ους (τὸ)</b> <span>[ᾰ]</span> pesanteur, poids, HDT. <i>2, 73, etc. ; d’où :</i><br><b>   I</b> <i>en mauv. part :</i> charge, fardeau, ESCHL. <i>Ch. 992 ;</i> SOPH. ARSTT. <i>etc. ; p. anal. en parl. de la sensation de lourdeur que causent les odeurs, les parfums,</i> SPT. <i>2Macc. 9, 10 ;</i> DIOSC. <i>4, 76, etc. ; de la pesanteur de certains organes du corps,</i> HPC. <i>396, 45 ; d’un sommeil lourd,</i> PLUT. <i>M. 345</i> a ; <i>fig</i>. charge accablante, lourd fardeau, <i>en parl. d’ordres, d’impôts, etc.,</i> POL. <i>1, 31, 5, etc. ;</i> σιγῆς β. SOPH. <i>Ant. 1256,</i> silence qui pèse ; β. πημονῆς, SOPH. <i>El. 939,</i> poids de la douleur ; <i>d’où abs</i>. malheur, infortune, ESCHL. <i>Pers. 945 ;</i><br><b>   II</b> <i>en b. part :</i><br><b>      1</b> plénitude, abondance (de fortune, de bonheur, <i>etc</i>.) EUR. <i>El. 1287 ; I.T. 416 ;</i> PLUT. <i>Alex. 48 ;</i><br><b>      2</b> force (d’une armée) POL. <i>1, 16, 4 ; 5, 104, 2 ;</i><br><b>      3</b> puissance, crédit, autorité, POL. <i>4, 32, 7 ;</i> DS. <i>19, 70 ;</i> PLUT. <i>Per. 37, Phoc. 3 ;</i><br><b>      4</b> gravité, <i>p. opp. à</i> χάρις <i>et à</i> ὥρα, PLUT. <i>Demetr. 2 ; M. 522</i> e.<br><span><b>Étym</b>. <i>cf</i>. βαρύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαρος - βάρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> 922 se réfère au poids,  au volume, à la masse, et l'un ou l'autre peut être oppressif.\n<br><br> est une charge dans la mesure où il est lourd,  un fardeau pour autant qu'il soit porté; de là  peut être soit lourd, soit léger.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G923":"<h1>Barsabas</h1>\n<p>Strong n° 923 <i>Prononciation [bar-sab-as']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Barsabas = « fils de Sabas »\n<ol>\n<li>surnom d'un certain Joseph (<a class=\"ref\" data-r=\"ACT1.23\">Actes 1.23</a>)</li>\n<li>surnom d'un certain Judas (<a class=\"ref\" data-r=\"ACT15.22\">Actes 15.22</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαρσαβας</font> &lt; בר־שבא - <font face=\"Georgia\">Βαρσαβᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G924":"<h1>Bartimaios</h1>\n<p>Strong n° 924 <i>Prononciation [bar-tim-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bartimée (Angl. Bartimaeus) = « fils de Timée »\n<ol><li>un certain aveugle, guéri par Jésus à Jéricho</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαρτιμαιος</font> &lt; ברטימי - <font face=\"Georgia\">Βαρτιμαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>\tNom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G925":"<h1>baruno</h1>\n<p>Strong n° 925 <i>Prononciation [bar-oo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>peser lourdement, surcharge, appesantir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαρύνω</b> <span>(<i>impf</i>. ἐϐάρυνον, <i>f</i>. βαρυνῶ, <i>ao</i>. ἐϐάρυνα, <i>pf. inus. ; pass. f</i>. βαρυνθήσομαι, <i>ao</i>. ἐϐαρύνθην, <i>pf. inus. en att., v. ci-dessous</i>)</span><br><b>      1</b> rendre pesant, alourdir : τινα, IL. <i>5, 664,</i> qqn ; εἵματα, OD. <i>5, 321,</i> ses vêtements (l’alourdissaient), <i>en parl. d’Ulysse naufragé ;</i> βαρύνεται γυῖα, IL. <i>19, 165,</i> ses membres sont alourdis ; βαρύνεσθαι τὴν χεῖρα, IL. <i>20, 480,</i> avoir la main alourdie (par une blessure) ; β. τὰ σκέλη, PLAT. ; τὴν κεφαλήν, PLAT. ATH. avoir les jambes lourdes, la tête lourde ; <i>fig</i>. être accablé (de douleur, de maux, <i>etc.) abs</i>. PD. <i>N. 7, 43 ;</i> SOPH. <i>O.R. 781 ; avec un dat</i>. χόλῳ βαρύνεσθαι, SOPH. <i>Aj. 41,</i> être accablé de ressentiment ;<br><b>      2</b> <i>fig</i>. fatiguer, importuner : δικαστάς, XÉN. <i>Ap. 9,</i> des juges ; <i>au pass</i>. être fatigué <i>ou</i> mécontent : διά τι, THC. <i>5, 7 ;</i> τινι, CALL. <i>Del. 244 ;</i> OPP. <i>H. 2, 59 ; 5, 65 ;</i> PLUT. <i>Num. 2 ;</i> τι, DH. <i>4, 14 ; 10, 17 ;</i> PLUT. <i>Cam. 1 ; M. 134</i> d, de qqe ch., supporter qqe ch. avec peine ; <i>avec un acc. de</i> pers. : τινα, PLUT. <i>Thes. 32,</i> supporter qqn avec peine ;<br><b>      3</b> <i>t. de gr</i>. prononcer avec l’accent grave (sans haussement de ton) <i>sur la dernière syllabe, càd</i>. ne frapper cette syllabe d’aucun accent, <i>d’où</i> faire remonter l’accent, <i>en parl. du dialecte éolien,</i> DYSC. <i>Pron. 298</i> c ; DRAC. <i>21, 15, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. poét. 3 sg</i>. βάρυνε <span>[ῡ]</span> IL. <i>5, 664. Ao. pass. 3 pl. poét</i>. βάρυνθεν, PD. <i>N. 7, 43. Pf</i>. βεϐάρυμμαι, <i>d’où 3 pl</i>. βεϐάρυνται, SPT. <i>Nah. 2, 9 ; inf</i>. βεϐαρύνθαι, ARSTT. <i>Physiogn. 6, 10 ; mais</i> βεϐάρυμαι, <i>d’où part</i>. βεϐαρυμένος, HPC. <i>Ep. 9, 374 Littré (var</i>. βεϐαρημένος <i>Hercher</i>).<br><span><b>Étym</b>. βαρύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαρυνω - βαρύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G926":"<h1>barus</h1>\n<p>Strong n° 926 <i>Prononciation [bar-ooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un poids qui pèse lourd</li>\n<li>métaph. :\n<ol type=\"a\">\n<li>onéreux</li>\n<li>sévère</li>\n<li>grave\n<ol>\n<li>un grand moment</li>\n</ol>\n</li>\n<li>violent, cruel, impitoyable</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαρύς, εῖα, ύ</b> <span>[ᾰ]</span><br><b>   I</b> pesant, lourd, <i>p. opp. à</i> κοῦφος, HDT. <i>4, 150 ;</i> PLAT. <i>Theæt. 152</i> a, <i>etc. ;</i> βαρύτερος ὁπλίτης, PLAT. hoplite pesamment armé ; τὸ βαρύτατον τοῦ στρατεύματος, XÉN. <i>Cyr. 5, 3, 37 ;</i> τὰ βαρέα τῶν ὅπλων, POL. <i>1, 76, 3,</i> corps de troupes pesamment armées ; <i>en parl. d’aliments,</i> lourd, indigeste, P. EG. <i>1, 9 ;</i> ATH. <i>116</i> e <i>et f ; fig</i>. lourd, pénible à supporter, intolérable (douleur, malheur, <i>etc</i>.) IL. <i>1, 97 ; 2, 111, etc. ;</i> OD. <i>7, 197, etc. ;</i> ESCHL. <i>Pers. 1044, etc. ;</i> SOPH. <i>Ph. 1045 ; Tr. 1202 ; O.R. 546 ;</i> PLAT. <i>Crit. 43</i> d, <i>etc. ; en parl. de pers</i>. qui est à charge, insupportable, PLUT. <i>504</i> c ; ANTH. <i>11, 326, etc. ; p. ext. ou anal. :</i><br><b>      1</b> fort, puissant, redoutable : χεὶρ β. IL. <i>1, 219 ;</i> POL. <i>31, 25, 4,</i> main lourde, <i>càd</i>. forte, puissante ; β. γείτονες, POL. <i>1, 10, 6,</i> voisins puissants ; β. ὀδμή, HDT. <i>6, 19 ;</i> XÉN. STR. <i>etc</i>. odeur forte <i>ou</i> désagréable ;<br><b>      2</b> <i>en parl. du son,</i> grave, <i>p. opp. à</i> ὀξύς, OD. <i>9, 257 ;</i> SOPH. <i>Ph. 208 ; p. opp. à</i> ὀξύς <i>et à</i> μέσος, PLAT. <i>Crat. 399</i> a ; ARSTT. <i>Rhet. 3, 1, 4, etc. ;</i> βαρυτάτη χορδή, PLAT. la corde la plus grave ; ἡ βαρεῖα (<i>s.-e</i>. προσῳδία) GRAMM. ; τὸ βαρύ, DH. l’accent grave ; <i>adv</i>., βαρὺ <i>ou</i> βαρέα στενάχειν, IL. <i>8, 334 ;</i> OD. <i>5, 420, etc</i>. pousser des gémissements profonds (<i>litt</i>. graves) ; <i>fig. en parl. de pers</i>. grave, digne, imposant, ARSTT. <i>Rhet. 2, 17, 4 ;</i><br><b>   II</b> rendu lourd, alourdi, appesanti : β. σὺν γήρᾳ, SOPH. <i>O.R. 17 ;</i> ἐν γήρᾳ, SOPH. <i>Aj. 1017 ;</i> ὑπὸ γήρως, EL. <i>V.H. 9, 1,</i> alourdi par la vieillesse ; β. νόσῳ, SOPH. <i>Tr. 235,</i> alourdi par la maladie ; ὑπὸ τῆς μέθης, PLUT. <i>M. 595</i> f, alourdi par l’ivresse ; <i>abs</i>. β. βάσις, SOPH. <i>Tr. 966,</i> marche pénible.<br><span>•<i> Cp</i>. βαρύτερος, POL. <i>1, 17, 3 ; 1, 31, 7 ;</i> DS. <i>Exc. Vat. p. 70 Mai ; etc.</i> <i>• Sup</i>. βαρύτατος, XÉN. <i>Cyr. 5, 3, 37 ;</i> POL. <i>6, 14, 3</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>rh₂-u-, lourd ; <i>cf. lat</i>. gravis, brūtus, <i>sscr</i>. gurú-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαρυς - βαρύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Actes (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G927":"<h1>barutimos</h1>\n<p>Strong n° 927 <i>Prononciation [bar-oo'-tim-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>important, grande valeur, très précieux, coûteux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαρύ·τιμος, ος, ον</b> <span>[ᾰῠῑ]</span><br><b>      1</b> cher, précieux, STR. <i>798 ;</i> NT. <i>Matth. 26, 7 ;</i><br><b>      2</b> aux lourdes vengeances, ESCHL. <i>Suppl. 25</i>.<br><span><b>Étym</b>. β. τιμή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαρυ-τιμος - βαρύτιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G928":"<h1>basanizo</h1>\n<p>Strong n° 928 <i>Prononciation [bas-an-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre à l'épreuve (des métaux) par une pierre de touche, pierre siliceuse utilisée pour la vérification de la pureté de l'or ou de l'argent par examen d'une rayure par cette pierre</li>\n<li>interroger en soumettant à la torture, éprouver</li>\n<li>torturer, malmener,</li>\n<li>vexer gravement, tourmenter</li>\n<li>être harcelé, affligé, tourment (moral)</li>\n<ol type=\"a\">\n<li>de ceux qui, en mer, naviguent avec le vent en face</li>\n</ol>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασανίζω</b> <span>(<i>f</i>. ιῶ, <i>ao</i>. ἐϐασάνισα ; <i>pass. ao</i>. ἐϐασανίσθην, <i>pf</i>. βεϐασάνισμαι)</span> <span>[ᾰᾰ]</span><br><b>   I</b> essayer avec la pierre de touche, <i>d’où</i> éprouver : χρυσόν, PLAT. <i>Gorg. 486</i> d, de l’or ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> examiner à fond, HPC. <i>281 ; d’où</i> vérifier, éprouver, PLAT. <i>Conv. 184</i> a, <i>etc. ; en parl. de pers</i>. mettre à l’épreuve, HDT. <i>1, 116, etc. ;</i> AR. <i>Ran. 802, etc. ;</i> βεϐασανισμένος εἰς δικαιοσύνην, PLAT. <i>Rsp. 331</i> c, qui est d’une justice éprouvée ;<br><b>      2</b> <i>p. suite,</i> mettre à la question, torturer, AR. <i>Ran. 616, 618 ;</i> ANT. <i>120, 8 ; fig</i>. LGN <i>10 ; au pass</i>. être mis à la question, THC. <i>7, 86 ; 8, 92, etc. ; p. ext</i>. être éprouvé (par la maladie, <i>etc</i>.) NT. <i>Matth. 8, 6 ; 14, 24 ;</i> βεϐασανισμένος, DH. <i>Thuc. 55,</i> tourmenté, torturé, <i>en parl. du style</i>.<br><span><b>Étym</b>. βάσανος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασανιζω - βασανίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G929":"<h1>basanismos</h1>\n<p>Strong n° 929 <i>Prononciation [bas-an-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tourment, torture\n<ol type=\"a\">\n<li>action de celui qui tourmente</li>\n<li>état de celui qui est tourmenté</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασανισμός, οῦ (ὁ)</b> <span>[ᾰᾰ]</span> mise à la question, torture, ALEX. (ATH. <i>30</i> f) ; NT. <i>Apoc. 9, 5 ; 14, 10, etc</i>.<br><span><b>Étym</b>. βασανίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασανισμος - βασανισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G930":"<h1>basanistes</h1>\n<p>Strong n° 930 <i>Prononciation [bas-an-is-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui tire la vérité par l'usage de la torture\n<ol type=\"a\">\n<li>un inquisiteur, un bourreau dont la fonction est de torturer ou de faire mourir, tortionnaire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασανιστής, οῦ (ὁ)</b> <span>[ᾰᾰ]</span> qui met à la question, bourreau, ANT. <i>112, 19 ;</i> DÉM. <i>978, 11 ;</i> PLUT. <i>M. 498</i> d, <i>etc</i>.<br><span><b>Étym</b>. βασανίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασανιστής</font>\n<br><br>vient de \n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)\n<ul type=\"square\">\n<li>Matthieu 18.34</li>\n</ul>\n</li>\n</ul>\n</td></tr>\n</table>","G931":"<h1>basanos</h1>\n<p>Strong n° 931 <i>Prononciation [bas'-an-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le chevalet ou instrument de torture par lequel on force à dire la vérité</li>\n<li>torture, tourment, peine aiguë, épreuve\n<ol type=\"a\">\n<li>peine de la maladie</li>\n<li>de ceux qui iront en enfer après la mort</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάσανος, ου (ἡ)</b> <span>[ᾰᾰ]</span><br><b>   I</b> pierre de touche (<i>lat</i>. lapis Lydius), PD. <i>P. 10, 67 ;</i> THGN. <i>417, 450 ;</i> ARSTT. <i>Col. 3, 7 ;</i><br><b>   II</b> <i>p. suite, fig. :</i><br><b>      1</b> moyen de vérification, moyen d’éprouver, épreuve, HDT. <i>8, 110 ;</i> SOPH. <i>O.R. 510 ;</i> PLAT. <i>Leg. 648</i> b, <i>etc. ;</i><br><b>      2</b> <i>part</i>. épreuve par la torture, mise à la question, ANT. <i>112, 24, etc. ;</i> IS. <i>70, 34, etc. ; au plur</i>. aveux arrachés par la torture, DÉM. <i>1254, 9 ; p. ext</i>. souffrance causée par la maladie, SEXT. <i>M. 6, 24 ;</i> NT. <i>Matth. 4, 24</i>.<br><span><b>Étym</b>. <i>emprunt, en passant par le lydien, à l’égyptien</i> baḫan, <i>sorte de pierre de touche pour l’or ; lat</i>. basalten, <i>leçon fausse de</i> basaniten (PLIN. <i>H.N. 36, 58) a donné franç</i>. basalte.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασανος - βάσανος</font>\n<br><br>Voir définition  TDNT – , </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G932":"<h1>basileia</h1>\n<p>Strong n° 932 <i>Prononciation [bas-il-i'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pouvoir royal, royauté, domination, autorité, dignité royale\n<ol type=\"a\">\n<li>l'autorité qui gouverne un royaume</li>\n<li>le pouvoir royal de Jésus, comme Messie triomphant</li>\n<li>le pouvoir royal et la dignité conférés aux Chrétiens dans le royaume du Messie</li>\n</ol>\n</li>\n<li>un royaume, le territoire soumis à l'autorité d'un roi</li>\n<li>utilisé dans le N.T. en référence au règne du Messie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασιλεία, ας (ἡ)</b> <span>[ᾰῐ]</span><br><b>   I</b> royauté, HDT. <i>2, 120 ;</i> THC. <i>2, 95 ;</i> XÉN. <i>Cyr. 8, 7, 13 ; 8, 8, 1, etc. ; p. suite :</i><br><b>      1</b> le roi, SPT. <i>1Macc. 6, 47 ; 8, 18 ;</i> NT. <i>Apoc. 1, 6 ;</i> DL. <i>5, 19 ; etc. ; plur</i>. αἱ βασιλεῖαι, SPT. <i>Reg. tit</i>. les Livres des Rois ;<br><b>      2</b> royaume, HDT. <i>4, 5 ; 4, 7 ;</i> DS. <i>20, 25 ;</i> SPT. <i>1Macc. 1, 16, etc. ;</i><br><b>      3</b> insigne de la royauté, diadème, DS. <i>1, 47 ;</i><br><b>   II</b> fonction de l’archonte-roi, <i>à Athènes,</i> PAUS. <i>1, 2, 3, ou</i> d’un magistrat d’Éphèse, DL. <i>9, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. βασιληΐη, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. βασιλεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασιλεια - βασιλεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n160 fois dans 152 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (56)</li>\n<li>Marc (20)</li>\n<li>Luc (45)</li>\n<li>Jean (5)</li>\n<li>Actes (8)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (5)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G933":"<h1>basileion</h1>\n<p>Strong n° 933 <i>Prononciation [bas-il'-i-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la cour, le palais royal</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασίλειος, ος</b> <i>ou</i> <b>α, ον</b> <span>[ᾰῐ]</span><br><b>   I</b> de roi, royal, OD. <i>16, 401 ;</i> HÉS. <i>O. 125 ;</i> HDT. <i>1, 35 ; 3, 61, etc</i>. DH. PLUT. <i>etc. ;</i> β. σῦκα, PHILÉM. GR. (ATH. <i>76</i> f) figues royales, <i>sorte de belles figues ; subst</i>. τὸ βασίλειον :<br><b>      1</b> demeure <i>ou</i> résidence royale, HDT. <i>4, 20 ;</i> XÉN. <i>Cyr. 2, 4, 3 et 4, etc. ; d’ord. au plur</i>. HDT. <i>1, 30, etc. ;</i><br><b>      2</b> capitale d’un royaume, POL. <i>3, 15, 3, etc. ;</i> DS. <i>20, 24 ;</i> STR. <i>495, etc. ;</i><br><b>      3</b> trésor royal, HDT. <i>2, 149 ;</i> DC. <i>68, 2 ; 73, 5 ;</i><br><b>      4</b> insigne de la royauté, diadème, PLUT. <i>M. 358</i> d ;<br><b>   II</b> de l’archonte-roi, <i>à Athènes,</i> βασίλειος στοά, AR. <i>Eccl. 685 ;</i> DÉM. <i>776, 20, etc</i>. portique où siégeait l’archonte-roi ;<br><b>   III</b> <i>subst</i>. τὸ βασίλειον (<i>v. ci-dessus</i> I) :<br><b>      1</b> sorte de parfum, SAPPH. (ATH. <i>690</i> e) ;<br><b>      2</b> <i>n. de diverses plantes,</i> DIOSC. <i>Noth. 443, 459</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. βασίλειος, AR. DÉM. <i>ll. cc. etc. ou</i> βασιλεία, ESCHL. <i>Pers. 589 ;</i> DS. <i>Exc. p. 82 Mai. ;</i> PAUS. <i>3, 1, 5, etc. — Ion</i>. βασιλήϊος, OD. HÉS. <i>ll. cc. ; fém</i>. βασιλήϊος, NONN. <i>Jo. 224, 14 ; ou</i> βασιληΐη, HDT. <i>4, 68 ; 7, 209 ;</i> EUR. <i>El. 186. Éol</i>. βασιλῇος, MÉLINNO (STOB. <i>1, 204 Gaisf</i>.).<br><span><b>Étym</b>. βασιλεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασιλειον - βασίλειος</font>\n<br><br>de </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G934":"<h1>basileios</h1>\n<p>Strong n° 934 <i>Prononciation [bas-il'-i-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>royal, du roi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασίλειος, ος</b> <i>ou</i> <b>α, ον</b> <span>[ᾰῐ]</span><br><b>   I</b> de roi, royal, OD. <i>16, 401 ;</i> HÉS. <i>O. 125 ;</i> HDT. <i>1, 35 ; 3, 61, etc</i>. DH. PLUT. <i>etc. ;</i> β. σῦκα, PHILÉM. GR. (ATH. <i>76</i> f) figues royales, <i>sorte de belles figues ; subst</i>. τὸ βασίλειον :<br><b>      1</b> demeure <i>ou</i> résidence royale, HDT. <i>4, 20 ;</i> XÉN. <i>Cyr. 2, 4, 3 et 4, etc. ; d’ord. au plur</i>. HDT. <i>1, 30, etc. ;</i><br><b>      2</b> capitale d’un royaume, POL. <i>3, 15, 3, etc. ;</i> DS. <i>20, 24 ;</i> STR. <i>495, etc. ;</i><br><b>      3</b> trésor royal, HDT. <i>2, 149 ;</i> DC. <i>68, 2 ; 73, 5 ;</i><br><b>      4</b> insigne de la royauté, diadème, PLUT. <i>M. 358</i> d ;<br><b>   II</b> de l’archonte-roi, <i>à Athènes,</i> βασίλειος στοά, AR. <i>Eccl. 685 ;</i> DÉM. <i>776, 20, etc</i>. portique où siégeait l’archonte-roi ;<br><b>   III</b> <i>subst</i>. τὸ βασίλειον (<i>v. ci-dessus</i> I) :<br><b>      1</b> sorte de parfum, SAPPH. (ATH. <i>690</i> e) ;<br><b>      2</b> <i>n. de diverses plantes,</i> DIOSC. <i>Noth. 443, 459</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. βασίλειος, AR. DÉM. <i>ll. cc. etc. ou</i> βασιλεία, ESCHL. <i>Pers. 589 ;</i> DS. <i>Exc. p. 82 Mai. ;</i> PAUS. <i>3, 1, 5, etc. — Ion</i>. βασιλήϊος, OD. HÉS. <i>ll. cc. ; fém</i>. βασιλήϊος, NONN. <i>Jo. 224, 14 ; ou</i> βασιληΐη, HDT. <i>4, 68 ; 7, 209 ;</i> EUR. <i>El. 186. Éol</i>. βασιλῇος, MÉLINNO (STOB. <i>1, 204 Gaisf</i>.).<br><span><b>Étym</b>. βασιλεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασιλειος - βασίλειος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G935":"<h1>basileus</h1>\n<p>Strong n° 935 <i>Prononciation [bas-il-yooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chef du peuple, prince, seigneur d'un territoire, roi</li>\n<li>le Roi Messianique, le roi des rois</li>\n<li>Dieu comme roi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασιλεύς, έως (ὁ)</b> <span>[ᾰῐ]</span><br><b>   I</b> roi, chef souverain, HOM. (IL. <i>1, 231, etc.) etc. ; joint à</i> ἀνήρ (ἀνὴρ β.) IL. <i>3, 170 ;</i> OD. <i>24, 253 ; ou à</i> ἄναξ (β. ἄναξ) OD. <i>20, 194 ; part</i>. ὁ μέγας β. HDT. <i>1, 188,</i> le grand roi, le roi de Perse (<i>mais,</i> οἱ μεγάλοι βασιλῆς, SOPH. <i>Aj. 189,</i> les rois suprêmes, les rois des rois, <i>càd</i>. les Atrides) ; <i>de même en parl. du roi de Perse,</i> ὁ ἄνω β. XÉN. <i>An. 7, 1, 28, etc. ; ou simpl</i>. ὁ βασιλεύς, AR. <i>Ach. 61, etc., ou, sans article,</i> βασιλεύς, THC. XÉN. DÉM. <i>etc. ; touj. sans article, en ce sens, dans les inscr. att</i>. CIA. <i>2, 86, 3 (376/364 av. J.C.) ; mais, avec l’article, en parl. d’autres rois (rois de Lacédémone, de Macédoine, etc</i>.) CIA. <i>2, 332, 37 (268/262 av. J.C.) ; 297, 13 (299 av. J.C.) etc. ; à Rome,</i> ὁ β. l’empereur, <i>après Auguste,</i> APP. HDN, NT. ;<br><b>   II</b> <i>p. ext. ou p. anal. :</i><br><b>      1</b> <i>dans Hom., part. dans l’Od</i>. οἱ β. les chefs de familles qui se partagent le pays, OD. <i>1, 394 ; 8, 390, etc. ; de même, primit. à Athènes,</i> ὁ β. le chef du γένος (<i>v. Fustel, Cité ant. L. IV, c. 4</i>) ;<br><b>      2</b> fils de roi, prince, XÉN. <i>Œc. 4, 16 ;</i><br><b>      3</b> satrape (perse), SEXT. <i>Rhet. p. 293, 22, en parl. de Tissapherne ;</i><br><b>      4</b> maître de maison, IL. <i>18, 556 ;</i> PD. ;<br><b>      5</b> <i>à Athènes,</i> le 2<sup>e</sup> des neuf archontes <i>ou</i> archonte-roi, ANT. <i>145, 41 ;</i> LYS. <i>103, 30 ;</i> PLAT. <i>Theæt. 210</i> d, <i>etc. ;</i><br><b>      6</b> roi d’un sacrifice (<i>lat</i>. rex sacrorum, rex sacrificus, rex sarcrificulus), DC. <i>54, 27, 3 ; cf</i>. DH. ;<br><b>      7</b> roi d’un festin (<i>cf</i>. συμποσίαρχος), PLUT. <i>M. 622</i> a, LUC. <i>Sat. 4 ;</i><br><b>      8</b> tout homme le plus remarquable de ceux de sa condition <i>ou</i> de sa profession, LUC. <i>Rh. præc. 11 ;</i> PHILSTR. <i>V. soph. 2, 586, 598, etc. ; p. anal. en parl. de l’aigle,</i> le roi (des oiseaux), LUC. ;<br><b>   III</b> roitelet (<i>lat</i>. regulus) oiseau, ARSTT. <i>H.A. 9, 11, 5</i>.<br><span>•<i> Cp</i>. βασιλεύτερος, IL. <i>9, 160, 392 ;</i> OD. <i>15, 533</i>. <i>• Sup</i>. βασιλεύτατος IL. <i>9, 69</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion</i>. βασιλῆος. <i>Acc. att</i>. βασιλέα (<i>par contract</i>. βασιλῆ, <i>seul</i>. ORACL. <i>dans</i> HDT. <i>7, 220 ;</i> EUR. <i>fr. 781, 25) ou</i> βασιλεϳα, CIA. <i>2, 263, 15 (303 av. J.C.) ; 312, 36 (286 av. J.C.) ; v. Meisterh. p. 36. Plur. nom</i>. βασιλεῖς, <i>ion</i>. βασιλῆες, <i>att</i>. βασιλῆς, SOPH. <i>Aj. 189, 959 ; acc. att</i>. βασιλέας, ARSTT. <i>Pol. 3, 13, 25 ;</i> CIA. <i>1, 61, 12 (409 av. J.C.), postér</i>. βασιλεῖς, CIA. <i>2, 243, 7 (peu après 307 av. J.C</i>.) ; <i>251, 3 (307/301 av. J.C</i>.) ; <i>263, 20 (303 av. J.C</i>.).<br><span><b>Étym</b>. <i>pré-grec ; cf. myc</i>. qa-si-re-u, chef <i>de rang inférieur</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασιλευς - βασιλεύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n117 fois dans 107 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (22)</li>\n<li>Marc (12)</li>\n<li>Luc (11)</li>\n<li>Jean (16)</li>\n<li>Actes (20)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (3)</li>\n<li>Hébreux (7)</li>\n<li>1 Pierre (2)</li>\n<li>Apocalypse (23)</li>\n</ul>\n</td></tr>\n</table>","G936":"<h1>basileuo</h1>\n<p>Strong n° 936 <i>Prononciation [bas-il-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être roi, exercer le pouvoir royal, régner\n<ol type=\"a\">\n<li>du gouverneur d'une province</li>\n<li>de l'autorité du Messie</li>\n<li>du règne des Chrétiens dans le millénium</li>\n</ol>\n</li>\n<li>métaph : exercer la plus haute influence, contrôler</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασιλεύω</b> <span>(<i>f</i>. εύσω, <i>ao</i>. ἐϐασίλευσα, <i>pf</i>. βεϐασίλευκα)</span> <span>[ᾰῐ]</span><br><b>A <i>intr</i>.<br>   I</b> être roi, <i>d’où :</i><br><b>      1</b> <i>propr</i>. être roi, régner, IL. <i>2, 203, etc. ;</i> OD. <i>1, 392, etc. ;</i> ἐν Ἰθάκῃ, OD. <i>1, 401 ;</i> ἐν πόλει, PLAT. dans Ithaque, dans une cité ; ἐν ὑμῖν, OD. <i>2, 47,</i> parmi vous ; ἐν Πέρσαις, XÉN. chez les Perses ; κατὰ δῆμον, OD. <i>22, 52,</i> sur le peuple ; <i>avec le gén</i>. β. Ἀχαιῶν, OD. <i>1, 401,</i> régner sur les Achéens, <i>càd</i>. sur les Grecs ; <i>avec le dat</i>. β. Γιγάντεσσιν, OD. <i>7, 59,</i> régner sur les Géants ; <i>avec le gén. du pays sur lequel on règne,</i> OD. <i>11, 285 ; ou avec</i> ἐπί <i>et l’acc</i>. SPT. <i>1Macc. 1, 16 ; en parl. d’une femme,</i> être reine, <i>càd</i>. femme du roi, IL. <i>6, 425 ; postér. en parl. d’une ville :</i> ἡ βασιλεύουσα πόλις, ATH. <i>98</i> c, la cité impériale, <i>en parl. de Rome ; au pass</i>. être gouverné par un roi, PD. <i>P. 4, 107 ;</i> PLAT. <i>Rsp. 576</i> d ; ARSTT. <i>Pol. 3, 14, 1, etc. ; d’où</i> être gouverné souverainement, PLAT. <i>Leg. 684</i> a ; LYS. <i>192, 22 ;</i><br><b>      2</b> devenir roi (<i>part. à l’ao</i>.) HDT. <i>1, 130 ;</i> THC. <i>2, 99 ;</i> XÉN. <i>Hell. 3, 3, 3 ;</i><br><b>      3</b> vivre en roi, PLUT. <i>M. 101</i> e ; NT. <i>1Cor. 4, 8 ;</i><br><b>      4</b> être maître absolu de, <i>dat</i>. THCR. <i>Idyl. 21, 60 ;</i><br><b>   II</b> être partisan de la royauté, PLUT. <i>Syll. 42 ;</i><br><b>B <i>tr.</i></b> faire <i>ou</i> désigner roi, <i>acc</i>. SPT. <i>Judith 9, 6 ; 9, 18 ; 1Reg. 8, 22, etc</i>.<br><span><b>Étym</b>. βασιλεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασιλευω - βασιλεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 18 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (3)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (3)</li>\n<li>1 Timothée (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G937":"<h1>basilikos</h1>\n<p>Strong n° 937 <i>Prononciation [bas-il-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui appartient au roi, royal\n<ol type=\"a\">\n<li>d'un homme, le ministre d'un prince, un de la cour, officier royal</li>\n</ol>\n</li>\n<li>assujetti à un roi\n<ol type=\"a\">\n<li>un pays</li>\n</ol>\n</li>\n<li>convenable ou digne d'un roi, royal</li>\n<li>métaph : principal, chef</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασιλικός, ή, όν</b> <span>[ᾰσῐ]</span><br><b>   I</b> qui concerne un roi, de roi, royal, HDT. <i>2, 173 ;</i> ESCHL. PLAT. <i>etc. ; p. opp. à</i> τυραννικός, ARSTT. <i>Pol. 3, 14, 11 ;</i> οἱ βασιλικοί, POL. <i>8, 12, 10 ;</i> PLUT. <i>etc</i>. ceux qui sont attachés à la personne <i>ou</i> au service du roi (officiers de la maison du roi, courtisans, ambassadeurs, <i>etc.) ; ou</i> partisans du roi, troupes royales, STR. APP. ; ἐγκλήματα β. POL. <i>26, 5, 1,</i> accusations de haute trahison ; τὰ βασιλικά, les prérogatives royales, SPT. <i>1Macc. 15, 8, etc. ; ou</i> tributs, impôts, SPT. <i>1Esdr. 1, 7 ; 1 Macc. 10, 43, etc. ;</i> JOS. <i>A.J. 13, 2 ; etc. ;</i><br><b>   II</b> qui convient à un roi, digne d’un roi, XÉN. <i>Œc. 21, 40 ; An. 1, 9, 1 ;</i> ISOCR. <i>20</i> d, <i>etc. ;</i><br><b>   III</b> <i>subst. :</i><br><b>      1</b> ἡ βασιλική (<i>s.-e</i>. τέχνη) PLAT. <i>Pol. 291</i> e, l’art de régner ; (<i>s.-e</i>. στοά) PLAT. <i>Charm. 153</i> a, le portique de l’archonte-roi, <i>à Athènes ; (s.-e</i>. οἰκία) VITR. <i>5, 1,</i> salle publique pour rendre la justice, et bourse de commerce, <i>à Rome (cf</i>. PLUT. <i>Cato ma. 5, 19 ;</i> APP. <i>Civ. 2, 26</i>) ;<br><b>      2</b> τὸ βασιλικόν, palais impérial, <i>à Rome,</i> DC. <i>60, 4 ; ou</i> trésor royal, DS. <i>2, 40 ; ou</i> décret royal, SPT. <i>Esth. 1, 19 ; ou</i> basilic, <i>sorte de plante,</i> ARSTT. <i>Plant. 1, 4, 10 ; ou</i> basilicon, <i>sorte d’onguent,</i> A. TR. <i>3, 175 ;</i><br><b>      3</b> οἱ βασιλικοί (<i>v. ci-dessus</i>) ;<br><b>      4</b> τὰ βασιλικά (<i>v. ci-dessus</i>).<br><span>•<i> Cp</i>. βασιλικώτερος, PLUT. <i>Alex. 21</i>. <i>• Sup</i>. βασιλικώτατος, XÉN. <i>An. 1, 9, 1 ;</i> PLUT. <i>M. 32</i> a.<br><span><b>Étym</b>. βασιλεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασιλικος - βασιλικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Actes (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G938":"<h1>basilissa</h1>\n<p>Strong n° 938 <i>Prononciation [bas-il'-is-sah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>reine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασίλισσα, ης (ἡ)</b> <span>[ᾰσῐ]</span><br><b>      1</b> reine, XÉN. <i>Œc. 9, 15 ;</i> THCR. <i>Idyl. 15, 24, etc. ; en parl. de la reine des abeilles,</i> ARR. <i>Epict. 3, 22, 99 ;</i><br><b>      2</b> femme de l’archonte-roi, ARSTT. <i>fr. 385 ;</i><br><b>      3</b> impératrice, <i>à Rome,</i> HDN <i>1, 7, 6</i>.<br><span><b><span class=\"arrow\"></span></b> βασίλιττα, <i>blâmé par</i> LUC. <i>J. voc. 8</i>.<br><span><b>Étym</b>. <i>fém. de</i> βασιλεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασιλισσα - βασίλισσα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G939":"<h1>basis</h1>\n<p>Strong n° 939 <i>Prononciation [bas'-ece]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire des pas, marcher</li>\n<li>ce avec quoi on fait un pas, le pied, plante des pieds</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάσις, εως (ἡ)</b> <span>[ᾰ]</span><br><b>   I</b> action de marcher, <i>d’où</i> marche, allure, ESCHL. <i>Eum. 36 ;</i> SOPH. <i>Aj. 8, etc. ;</i> οὐκ ἔχων βάσιν, SOPH. <i>Ph. 691,</i> n’ayant pas le pouvoir de marcher, impuissant à marcher ; <i>au plur</i>. τροχῶν βάσεις, SOPH. <i>El. 717,</i> le mouvement des roues ; <i>part</i>. marche réglée <i>ou</i> cadencée, cadence, rythme, PLAT. <i>Rsp. 399</i> e, <i>etc</i>. AR. <i>Th. 968 ; etc. ; t. de rhét</i>. mouvement rythmé d’une période, HERMOG., <i>p. ext., t. de métr. en parl. d’un pied unique ou d’une réunion de deux pieds,</i> DRAC. <i>124, 16 ;</i> LGN <i>fr. 3 ;</i> BACCH. <i>22 ; cf</i>. ARSTT. <i>Pol. 2, 5, 14 ; Metaph. 13, 1 ;</i><br><b>   II</b> organe pour la marche :<br><b>      1</b> pied ; αἱ βάσεις, PLAT. <i>Tim. 92</i> a ; EUR. <i>I.A. 421 ;</i> NT. <i>Ap. 3, 7,</i> les pieds ; <i>p. opp. à</i> χεῖρες, PHIL. <i>1, 29, etc. ; au sg</i>. ARSTT. <i>p. 750, 4 Bkk. ;</i> APD. <i>3, 5, 3, etc. ;</i><br><b>      2</b> jambe, APD. <i>1, 3, 5 ;</i><br><b>   III</b> ce sur quoi l’on marche <i>ou</i> l’on se tient, base, piédestal, STR. <i>637 ; en parl. de vases, de machines,</i> support, embase : βάσις τρισκελής, HÉRON, embase à trois jambes <i>ou</i> patins ; <i>d’où</i> base, fondement, <i>en gén</i>. T. LOCR. <i>97</i> e ; <i>p. anal</i>. base d’un triangle, PLAT. <i>Tim. 55</i> b ; ARSTT. <i>An. pr. 1, 24, etc. ;</i> base <i>ou</i> point central d’une circonférence, ARCHIM. <i>Sph. cyl. 1, 17 ;</i> base <i>ou</i> siège d’un organe <i>ou</i> d’une partie du corps (<i>des yeux,</i> ANTH. <i>5, 87 ; de la cervelle,</i> PLUT. <i>M. 899</i> a ; <i>du cou,</i> PLUT. <i>Pyrrh. 34, etc</i>.).<br><span><b>Étym</b>. βαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασις - βάσις</font>\n<br><br>vient de baino (marcher)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G940":"<h1>baskaino</h1>\n<p>Strong n° 940 <i>Prononciation [bas-kah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parler en mal de quelqu'un, calomnier, médire</li>\n<li>apporter le mal sur quelqu'un par une invocation ou un mauvais œil</li>\n<li>charmer, ensorceler, fasciner, jeter un sort</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βασκαίνω</b> <span>(<i>f</i>. ανῶ, <i>v. ci-dessous</i>)</span><br><b>      1</b> jeter un sort, fasciner, ensorceler, ARSTT. <i>Probl. 34, 20 ;</i> THCR. <i>Idyl. 6, 39 ;</i><br><b>      2</b> <i>p. suite,</i> regarder d’un œil jaloux, porter envie à : τινί, DÉM. <i>464, 11,</i> à qqn ; τινί τινος, PHILSTR. <i>V. Ap. 6, 12 ;</i> RHÉT. <i>1, 575 W. ;</i> D. CHR. <i>2, 428,</i> à qqn au sujet de qqe ch. ; β. τινός, LUC. <i>Philops. 35 ;</i> ἐπί τινι, LUC. <i>Nav. 17 ;</i> τι, HDN <i>2, 4, 11,</i> voir qqe ch. de mauvais œil ;<br><b>      3</b> <i>p. suite</i> décrier, dénigrer, <i>acc</i>. DÉM. <i>94, 19 ; 291, 21 ;</i> DS. <i>4, 6 ;</i> LIB. <i>4, 519, 732 ; au pass</i>. être décrié, STR. <i>654</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. ἐϐάσκηνα, PHILSTR. <i>Ep. 12 ;</i> RHÉT. <i>1, 575 W. ou</i> ἐϐάσκανα, <i>d’où sbj. 2 sg</i>. βασκάνῃς, ARSTT. <i>Probl. 34, 20. Pass. ao. inf</i>. βασκανθῆναι, STR. <i>l. c</i>.<br><span><b>Étym</b>. βάσκανος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασκαινω - βασκαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G941":"<h1>bastazo</h1>\n<p>Strong n° 941 <i>Prononciation [bas-tad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre, soulever avec les mains, lever</li>\n<li>prendre dans le but de transporter, poser sur soi une chose à transporter</li>\n<li>porter, transporter\n<ol type=\"a\">\n<li>se transporter</li>\n<li>soutenir, supporter</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαστάζω</b> <span>(<i>impf</i>. ἐϐάσταζον, <i>f</i>. βαστάσω, <i>ao</i>. ἐϐάστασα, <i>pf. inus. ; v. ci-dessous</i>)</span> <i>litt</i>. mettre en mouvement, <i>d’où :</i><br><b>   I</b> lever :<br><b>      1</b> soulever (un objet lourd, un fardeau, <i>etc</i>.) λᾶαν ἀμφοτέρῃσι, OD. <i>11, 594, dout</i>. soulever une pierre avec les deux mains ; μέγα τόξον, OD. <i>21, 405,</i> soulever, soupeser un grand arc ;<br><b>      2</b> relever : τινὰ πεπτῶτα, SOPH. <i>Aj. 827,</i> un homme tombé ;<br><b>      3</b> soulever, lever légèrement (un voile) SOPH. <i>El. 1470 ;</i><br><b>      4</b> <i>fig</i>. exalter, célébrer, PD. <i>O. 12, 27 ; I. 3, 14 ;</i><br><b>      5</b> <i>fig</i>. tenir levé <i>ou</i> suspendu, balancer : ἐν γνώμᾳ, ESCHL. <i>Pr. 888 ;</i> φρενί, AR. <i>Th. 437,</i> dans son esprit ; πρᾶγμα, POL. <i>7, 13,</i> peser une affaire ;<br><b>   II</b> <i>p. suite,</i> porter : <i>d’où :</i><br><b>      1</b> porter, <i>au pr. :</i> φόρτον νώτοισι, BATR. <i>78,</i> un fardeau sur ses épaules ; τινὰ χεροῖν, SOPH. <i>El. 1129 ou</i> ἐν χεροῖν, EUR. <i>Alc. 19,</i> qqn dans ses bras ; τι πρὸ χειρῶν, EUR. <i>Rhes. 274 ; I.A. 36,</i> porter qqe ch. devant soi dans ses mains ; <i>p. ext</i>. tenir dans ses bras <i>ou</i> dans ses mains, tenir, SOPH. <i>Ph. 657 ; El. 905, etc. ;</i> χέρα χερί, ESCHL. <i>Ag. 34 ; ou simpl</i>. χέρα, EUR. <i>Alc. 917,</i> presser dans sa main la main (de qqn), <i>d’où</i> tenir embrassé : βαστάσαι δότε, SOPH. <i>O.C. 1105,</i> laissez-moi vous embrasser ; <i>au pass</i>. être dans les mains (de tous), <i>en parl. d’ouvrages,</i> ARSTT. <i>Rhet. 3, 12, 2 ;</i><br><b>      2</b> emporter, enlever : τὰς τραπέζας, ATH. <i>693</i> e, enlever les tables ; <i>d’où</i> emporter clandestinement, dérober, voler, POL. <i>32, 25, 4 ;</i> DL. <i>4, 59 ;</i> A. TR. <i>3, 176, etc. ; p. ext</i>. supprimer (une coutume) APP. <i>Civ. 1, 56</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. réc</i>. βαστάξω, CALLISTH. <i>1, 45 ;</i> MAUR. <i>Strat. 83 ;</i> SYMM. <i>Prov. 9, 12. Ao. réc</i>. ἐϐάσταξα, ANTH. <i>App. 324 ;</i> CALLISTH. <i>1, 3. Pass. réc. f</i>. βασταχθήσομαι, CALLISTH. <i>1, 42. Ao</i>. ἐϐαστάχθην, DS. <i>4, 59 ;</i> ATH. <i>693</i> e. <i>Ao.2 inf</i>. βασταγῆναι, ARTÉM. <i>2, 68. — Verbe homér. et de poésie att. à l’act. ; inus. en bonne prose att</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βασταζω - βαστάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 27 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (5)</li>\n<li>Jean (5)</li>\n<li>Actes (4)</li>\n<li>Romains (2)</li>\n<li>Galates (4)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G942":"<h1>batos</h1>\n<p>Strong n° 942 <i>Prononciation [bat'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une épine, ronce, buisson épineux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>βάτος, ου (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> ronce, <i>d’où</i> mûre sauvage, OD. <i>24, 230 ;</i> ANTH. <i>7, 315, etc. ;</i> βάτος Ἰδαία, DIOSC. <i>4, 38,</i> mûre sauvage du mt Ida, <i>càd</i>. framboise ;<br><b>      2</b> épine, <i>en gén</i>. ANTH. <i>5, 28</i>.<br><span><b><span class=\"arrow\"></span></b> ὁ βάτος, AR. <i>fr. 593 ;</i> TH. <i>H.P. 1, 5, 3 ;</i> POL. SPT. <i>etc</i>.</span><br>\n② <b>βάτος, ου (ὁ)</b> sorte de raie, <i>poisson,</i> ARSTT. <i>H.A. 2, 13, 6, etc. ; cf</i>. βατίς 2.<br>\n③ <b>βάτος, ου (ὁ)</b> mesure de 50 setiers <i>ou</i> de 3 amphores, SPT. <i>2Esdr. 7, 22 ;</i> NT. <i>Luc. 16, 6 ; cf</i>. βάδος.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βατος - βάτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G943":"<h1>batos</h1>\n<p>Strong n° 943 <i>Prononciation [bat'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un « bath », mesure Juive pour les liquides, d'environ 40 litres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάτος, ου (ὁ)</b> mesure de 50 setiers <i>ou</i> de 3 amphores, SPT. <i>2Esdr. 7, 22 ;</i> NT. <i>Luc. 16, 6 ; cf</i>. βάδος.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βατος - βάτος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G944":"<h1>batrachos</h1>\n<p>Strong n° 944 <i>Prononciation [bat'-rakh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une grenouille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάτραχος, ου (ὁ)</b> <span>[ᾰᾰ]</span><br><b>   I</b> grenouille, BATR. <i>6, 18, etc. ;</i> HDT. <i>4, 131, etc. ;</i> PLAT. <i>Theæt. 167</i> d, <i>etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> grenouille de mer <i>ou</i> baudroie (<i>lophius piscatorius</i> ou <i>barbatus</i> L.) <i>poisson aussi appelé</i> ἁλιεύς, ARSTT. <i>H.A. 5, 5, 3 ; 9, 37, 5 ;</i> ATH. <i>286</i> d ; PLUT. <i>M. 978</i> a, <i>etc. ;</i><br><b>      2</b> gonflement au-dessous de la langue (<i>lat</i>. rana, ranula) AÉT. ;<br><b>      3</b> partie supérieure du sabot d’un cheval, GEOP. <i>16, 1, 9</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. βάθρακος, HDT. (SCH.-IL. <i>4, 243) ; ou</i> βότραχος <i>ou</i> βρόταχος, XÉNOPHAN. (EM. <i>214, 42</i>).<br><span><b>Étym</b>. <i>probabl. pré-grec, p.-ê. onomatopée comme</i> βρεκεκεκέξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βατραχος - βάτραχος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G945":"<h1>battologeo</h1>\n<p>Strong n° 945 <i>Prononciation [bat-tol-og-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bégayer</li>\n<li>répéter sans cesse les mêmes choses, utiliser de nombreux mots inutiles, babiller, jaser. Certains supposent que le mot vient de Battus, roi de Cyrène, dont il est dit qu'il bégayait; d'autres pensent à Battus, un auteur prolixe de poèmes ennuyeux.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nMot apparenté : <b>βάτταλος</b>, <i>mieux que</i> <b>βάταλος, ου (ὁ) :<br>      1</b> le derrière, EUP. <i>82 Kock ;</i><br><b>      2</b> débauché, CLÉM. <i>266 ; sobriquet de Démosthène (par jeu de mots avec</i> βατταρίζω, (voir ci-dessous) <i>parce qu’étant jeune il prononçait le</i> ρ <i>comme un</i> λ) ESCHN. <i>41, 14 ;</i> DÉM. <i>288, 17 ;</i> PLUT. <i>etc</i>.<br><span><b>Étym</b>. Βάτταλος.</span><br><br>\n<b>βατταρίζω</b> <span>[τᾰ]</span> bredouiller, dire, des niaiseries, HIPPON. <i>fr. 108 ;</i> LUC. <i>J. tr. 27</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαττολογεω - βατταλογέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G946":"<h1>bdelugma</h1>\n<p>Strong n° 946 <i>Prononciation [bdel'-oog-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une chose folle, détestable\n<ol type=\"a\">\n<li>des idoles et choses appartenant à l'idolâtrie, abomination</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βδέλυγμα, ατος (τὸ)</b> objet d’horreur, cause d’abomination, SPT. <i>1Macc. 1, 54 ; Dan. 9, 27 ; etc. part</i>. culte des idoles, idoles <i>ou</i> idolâtrie, SPT. <i>Deut. 18, 9 ; 29, 17 ; 1Reg. 3, 11, 6, etc</i>.<br><span><b>Étym</b>. βδελύσσομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βδελυγμα - βδέλυγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G947":"<h1>bdeluktos</h1>\n<p>Strong n° 947 <i>Prononciation [bdel-ook-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>abominable, détestable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βδελυκτός, ή, όν</b>, dégoûtant, répugnant, abominable, NT. <i>Tit. 1, 16 ;</i> PHIL. <i>2, 261</i>.<br><span><b>Étym</b>. βδελύσσομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βδελυκτος - βδελυκτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G948":"<h1>bdelusso</h1>\n<p>Strong n° 948 <i>Prononciation [bdel-oos'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre sale, amener à être abhorré</li>\n<li>abominable, avoir en abomination</li>\n<li>métaph : abhorrer, détester</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βδελύσσω</b>, inspirer du dégoût <i>ou</i> de l’horreur, SPT. <i>1Macc. 1, 48 ; d’où, au pass. (pf</i>. ἐϐδέλυγμαι) être un objet de dégoût <i>ou</i> d’horreur, NT. <i>Apoc. 21, 8 ;</i><br><b><i>Moy</i>. βδελύσσομαι</b>, <i>att</i>. <b>βδελύττομαι</b> <span>(<i>f</i>. -ύξομαι, <i>ao</i>. ἐϐδελύχθην, <i>postér</i>. ἐϐδελυξάμην)</span><br><b>      1</b> éprouver du dégoût pour la nourriture, HPC. <i>606, 49 ; 607, 33 ; d’où, en gén</i>. éprouver du dégoût, AR. <i>Vesp. 792 ; Pl. 700 ;</i><br><b>      2</b> éprouver de l’horreur pour, <i>acc</i>. AR. <i>Lys. 794 ; joint à</i> δέδοικα καὶ πέφρικα, AR. <i>Nub. 1132, etc. ;</i> PLUT. <i>Alex. 57</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. ἐϐδελύχθην <i>au sens act</i>. AR. <i>Vesp. 792 (v. ci-dessus). Ao. moy. réc</i>. ἐϐδελυξάμην, SPT. <i>Lev. 20, 23 ;</i> JOS. <i>B.J. 6, 2, 10 ;</i> CHRYS. <i>7, 351. Act. réc. fut</i>. βδελύξω, SPT. <i>Lev. 20, 25 ; ao</i>. ἐϐδέλυξα, SPT. <i>Ex. 5, 21</i>.<br><span><b>Étym</b>. <i>cf</i>. βδελυρός <i>et</i> βδέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βδελυσσω - βδελύσσω</font>\n<br><br>vient peut-être d'un dérivé de bdeo (puer)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G949":"<h1>bebaios</h1>\n<p>Strong n° 949 <i>Prononciation [beb'-ah-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>stable, ferme</li>\n<li>métaph : sûr, véridique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βέϐαιος, ος</b> <i>ou</i> <b>α, ον</b>, <i>litt</i>. sur quoi l’on peut marcher, <i>d’où</i> ferme, solide :<br><b>   I</b> <i>au propre, en parl. de la terre ferme,</i> ARR. <i>An. 2, 21, 6 ; de la glace,</i> THC. <i>3, 23 ; p. ext. en parl. de toute chose solide :</i> β. ὄχημα, PLAT. <i>Phæd. 85</i> d, voiture solide ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> ferme, constant, <i>en parl. de pers</i>. φίλος β. ESCHL. <i>Pr. 297 ;</i> THC. <i>5, 43, etc</i>. ami sûr <i>ou</i> fidèle ; <i>en parl. de choses :</i> βεϐαία εἰρήνη, ISOCR. <i>77</i> a, <i>134</i> a, paix solide ; χάρις βέϐαιος, THC. <i>1, 32,</i> reconnaissance durable ; φιλία βέϐαιος, PLAT. <i>Conv. 183</i> c, amitié sûre <i>ou</i> fidèle ; <i>joint à</i> πιστός, SOPH. <i>Ph. 71 ; à</i> ἀληθής, PLAT. <i>Tim. 37</i> b, <i>etc. ;</i> τῆς διανοίας τὸ βέϐαιον, THC. <i>2, 89,</i> esprit ferme et résolu ;<br><b>      2</b> qui est à l’abri du danger : πύλαι βέϐαιοι, THC. <i>4, 67,</i> portes sûres, à l’abri de toute surprise ; σωτηρία βέϐαιος, AND. <i>8, 9,</i> salut assuré ;<br><b>      3</b> sûr, certain, <i>en parl. de choses :</i> τέκμαρ β. ESCHL. <i>Pr. 456,</i> preuve certaine ; β. τοξεύματα, SOPH. <i>Ant. 1086,</i> traits qui vont sûrement au but (<i>ou</i> lancés d’une main ferme, bien assurée) ; κίνδυνος β. THC. <i>3, 39,</i> danger certain ; <i>en parl. de pers</i>. βεϐαιότεροι ἂν ἦσαν μηδὲν νεωτεριεῖν, THC. <i>3, 11,</i> il serait plus certain qu’ils ne feraient aucun changement ; τὸ βέϐαιον, HDT. <i>7, 50,</i> la certitude.<br><span>•<i> Cp</i>. βεϐαιότερος, THC. <i>3, 11 et 39 ;</i> PLAT. <i>Phæd. 85</i> d ; <i>Conv. 209</i> c ; <i>etc.</i> <i>• Sup</i>. βεϐαιότατος, THC. <i>1, 124 ;</i> PLAT. <i>Leg. 838</i> d ; <i>Rsp. 535</i> a, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. βεϐαία, SOPH. <i>fr. 202 ;</i> EUR. <i>El. 1263 ;</i> ISOCR. <i>77</i> a, <i>etc. ;</i> βέϐαιος (<i>v. ci-dessus ; dans Thuc. Plat. etc. seul</i>. βέϐαιος).<br><span><b>Étym</b>. <i>rapport avec</i> βῆναι, βαίνω, <i>mais formation peu claire</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βεβαιος - βέβαιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (5)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G950":"<h1>bebaioo</h1>\n<p>Strong n° 950 <i>Prononciation [beb-ah-yo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rendre ferme, établir, confirmer, rendre sûr</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βεϐαιόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἐϐεϐαίωσα, <i>pf. inus</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> affermir, consolider : τὴν ἀρχήν, PLUT. <i>Syll. 22,</i> le pouvoir (de qqn) ;<br><b>      2</b> <i>p. suite,</i> réaliser, effectuer : πρᾶξιν, XÉN. <i>An. 7, 6, 17,</i> une entreprise ; λόγον, LYS. <i>161, 1,</i> tenir sa parole ; ἔργῳ βεϐαιούμενα, THC. <i>1, 23,</i> choses, réalisées en fait (<i>p. opp. à</i> ἀκοῇ λεγόμενα) ;<br><b>      3</b> assurer, garantir : τινὶ τὴν ἐλευθερίαν, THC. <i>1, 122,</i> la liberté à qqn ; νόμους β. DÉM. <i>524</i> sanctionner des lois ; <i>cf</i>. XÉN. <i>Cyr. 8, 8, 2 ; An. 7, 6, 17 ;</i><br><b>   II <i>intr.</i></b> se produire <i>ou</i> se manifester sûrement, HPC. <i>Epid. 1, 939 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἐϐεϐαιωσάμην)</span><br><b>      1</b> affermir, assurer pour soi-même (son pouvoir, son influence, <i>etc</i>.) THC. <i>6, 10 ;</i> PAUS. <i>3, 11, 4 ;</i> POL. <i>2, 51, 5, etc. ;</i> β. τινα, THC. <i>6, 34,</i> s’assurer les bonnes dispositions de qqn ;<br><b>      2</b> établir solidement (un fait, une preuve, <i>etc</i>.) par le raisonnement, PLAT. <i>Theæt. 169</i> e, <i>etc. ;</i> DÉM. <i>79, 12 ;</i><br><b>      3</b> garantir la possession de : τινί τι, IS. <i>53, 11,</i> de qqe ch. à qqn.<br><span><b>Étym</b>. βέϐαιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βεβαιοω - βεβαιόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G951":"<h1>bebaiosis</h1>\n<p>Strong n° 951 <i>Prononciation [beb-ah'-yo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>confirmation, affermissement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βεϐαίωσις, εως (ἡ) :<br>      1</b> action de consolider, d’affermir, THC. <i>1, 140 ;</i><br><b>      2</b> action de rendre assuré <i>ou</i> certain : εἰς βεϐαίωσιν, SPT. <i>Lev. 25, 23,</i> de toute certitude, certainement, absolument.<br><span><b>Étym</b>. βεϐαιόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βεβαιωσις - βεβαίωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G952":"<h1>bebelos</h1>\n<p>Strong n° 952 <i>Prononciation [beb'-ay-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>accessible, peut être foulé légalement\n<ol type=\"a\">\n<li>de lieux ou endroits</li>\n</ol>\n</li>\n<li>profane\n<ol type=\"a\">\n<li>commun, lieu public, non sacré</li>\n<li>des hommes, impie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βέϐηλος, ος, ον</b>, où l’on peut marcher, dont l’accès n’est pas interdit, <i>d’où :</i><br><b>   I</b> profane, <i>en parl. de lieux, p. opp. à</i> ἄϐατος, SOPH. <i>fr. 109 ; à</i> ἱερός, DH. <i>7, 8 ; joint à</i> ἄλσος, ESCHL. <i>Suppl. 509 ;</i> SOPH. <i>O.C. 10 ;</i> ἐν βεϐήλῳ, THC. <i>4, 97,</i> dans un lieu profane ; <i>en parl. de pers</i>. SOPH. <i>fr. 154 ; p. suite :</i><br><b>      1</b> non initié à, <i>gén</i>. ANTH. <i>9, 298 ;</i><br><b>      2</b> impur, EUR. <i>fr. 650 ;</i> PLAT. <i>Conv. 218</i> b ; <i>joint à</i> ἀνόσιος, PHIL. <i>1, 658 ; à</i> ἀκάθαρτος, PHIL. <i>2, 165 ; à</i> ἀκάθαρτος καὶ ἀνίερος, PHIL. <i>2, 235, etc. ;</i><br><b>   II</b> connu de tous, vulgaire (<i>p. opp. à</i> κεκρυμμένος, caché, secret), EUR. <i>Her. 404</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. βέϐαλος <span>[ᾱ]</span> LYSIS <i>Ep. ad Pyth. p. 52 Orell</i>.<br><span><b>Étym</b>. <i>rapport avec</i> βέϐηκα, βαίνω, <i>mais formation peu claire</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βεβηλος - βέβηλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G953":"<h1>bebeloo</h1>\n<p>Strong n° 953 <i>Prononciation [beb-ay-lo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>profaner, souiller</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βεϐηλόω-ῶ</b>, <i>f</i>. ώσω :<br><b>      1</b> profaner, <i>acc</i>. (un temple, <i>etc</i>.) HLD. <i>2, 25 ; 10, 36 ;</i> SPT. <i>Ex. 31, 14 ;</i> NT. <i>Matth. 12, 5 ;</i><br><b>      2</b> souiller, <i>acc</i>. SPT. <i>Lev. 21, 4 ;</i><br><b>      3</b> exclure (d’un lieu saint) comme profane, <i>au pass</i>. BAS. <i>2, 15</i>.<br><span><b>Étym</b>. βέϐηλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βεβηλοω - βεβηλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G954":"<h1>Beelzeboul</h1>\n<p>Strong n° 954 <i>Prononciation [beh-el-zeb-ool']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Béelzébul (Angl. Beelzebub) = « seigneur de la maison » ou « seigneur des mouches » ou « seigneur du fumier »\n<ol><li>un nom de Satan, le prince des mauvais esprits</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βεελζεβουλ</font> &lt; בעל־זבוב - <font face=\"Georgia\">Βεελζεβούλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G955":"<h1>Belial</h1>\n<p>Strong n° 955 <i>Prononciation [bel-ee'-al]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bélial (Angl. Belial) = « indignité, méchanceté, impiété »\n<ol><li>un nom de Satan, littéralement « vaurien »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βελιαλ</font> &lt; בליעל - <font face=\"Georgia\">Βελίαλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G956":"<h1>belos</h1>\n<p>Strong n° 956 <i>Prononciation [bel'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un projectile, dard, javelot, flèche, un trait</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βέλος, εος-ους (τὸ)</b> ce qu’on lance, HÉRON <i>122 ; d’où :</i><br><b>   I</b> toute arme de trait <i>ou</i> de jet, projectile, <i>part. :</i><br><b>      1</b> javelot, HOM. (IL. <i>4, 498, etc. ;</i> OD. <i>20, 305, etc.), etc. ;</i> ὑπὲκ βελέων, IL. <i>4, 465 ;</i> ἐκ βελέων, IL. <i>11, 163 ;</i> ἔξω βελῶν, XÉN. <i>Cyr. 3, 3, 69 ;</i> ἔξω βέλους, LUC. <i>H. conscr. 4,</i> hors de la portée du trait ; ἐντὸς βέλους, DS. <i>20, 6, etc. ;</i> εἴσω βέλους, ARR. <i>An. 1, 6, 8,</i> en deçà de la portée du trait ;<br><b>      2</b> quartier de roc, OD. <i>9, 495 ;</i><br><b>      3</b> traits de la foudre, <i>au sg</i>. ESCHL. <i>Pr. 358 ;</i> SOPH. <i>Tr. 1087 ;</i> EUR. <i>Suppl. 860 ;</i> HDT. <i>4, 79 ; au plur</i>. PD. <i>N. 10, 15 ;</i><br><b>      4</b> tout projectile, toute chose lancée <i>ou</i> qui atteint en tombant (<i>banc,</i> OD. <i>17, 464 ;</i> δύσομϐρα βέλη, SOPH. <i>Ant. 359,</i> atteintes importunes de la pluie ; τὰ βέλη, le matériel balistique, l’artillerie : ἐνεργῆ ἔστω πάντα τὰ βέλη, PHIL. BYZ. faites donner toute l’artillerie, <i>etc</i>.) ;<br><b>   II</b> <i>p. ext</i>. arme qu’on brandit <i>ou</i> que darde un animal :<br><b>      1</b> dard d’un scorpion, ESCHL. <i>fr. 165 ;</i> OPP. <i>H. 1, 591 ;</i><br><b>      2</b> épée, SOPH. <i>Aj. 658 ;</i> EUR. <i>El. 1159 ;</i> AR. <i>Ach. 345 ;</i><br><b>      3</b> <i>c</i>. βελόνη, EL. <i>V.H. 9, 13 ;</i><br><b>      4</b> flèches <i>ou</i> traits (<i>d’Apollon pour les hommes, d’Artémis pour les femmes) qui procurent une mort douce et soudaine,</i> IL. <i>24, 759 ;</i> OD. <i>3, 280</i> (<i>v</i>. ἀγανός) ;<br><b>      5</b> <i>p. anal. en parl. de tout ce qui cause une douleur vive et aiguë</i> (douleur causée par un coup, IL. <i>14, 439 ;</i> douleurs de l’enfantement, IL. <i>11, 269 ;</i> THCR. <i>Idyl. 27, 28 ;</i> souffrance causée par le froid, SOPH. <i>Ant. 358 ; etc</i>.) ;<br><b>      6</b> <i>fig. en parl. de tout ce qui blesse ou atteint le cœur ou l’esprit (regards qui portent dans le cœur ou qui expriment l’amour,</i> ESCHL. <i>Ag. 742 ; ou la pitié,</i> ESCHL. <i>Ag. 240 ; p. suite,</i> traits de l’amour, ESCHL. <i>Pr. 649 ; p. ext</i>. douleur que cause l’amour, ARISTÉN. <i>1, 16 ;</i> HLD. <i>318 ; en parl. d’angoisses, de crainte,</i> PD. <i>N. 1, 71 ; en parl. d’arguments dans une discussion,</i> ESCHL. <i>Eum. 679 ;</i> PLAT. <i>Phil. 23</i> b.<br><span><b>Étym</b>. βάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βελος - βέλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G957":"<h1>beltion</h1>\n<p>Strong n° 957 <i>Prononciation [bel-tee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>meilleur, mieux, très bien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βελτίων, ον, ον</b>, <i>gén</i>. <b>ονος</b> <span>[ῑ <i>att., mais voy. ci-dessous</i>]</span> <i>compar. de</i> ἀγαθός, meilleur, ATT. ; <i>p. opp. à</i> χείρων, THC. <i>8, 87 ; neutre adv</i>. βέλτιον, ATT. mieux ; βέλτιόν (ἐστι) <i>avec l’inf</i>. il est prélérable de, il vaut mieux, ATT. ; <i>absol</i>. cela est préférable.<br><span><b><span class=\"arrow\"></span></b> <i>Neutre</i> βέλτιον, <i>p. except. avec</i> ῐ, MIMNERME <i>2, 10</i>.<br><span><b>Étym</b>. <i>Cf</i>. βέλτιστος <i>et</i> βέλτερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βελτιων - βελτίων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G958":"<h1>Beniamin</h1>\n<p>Strong n° 958 <i>Prononciation [ben-ee-am-een']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Benjamin = « fils de la main droite » ou « fils de la bonne fortune »\n<ol>\n<li>douzième fils de Jacob</li>\n<li>la tribu de Benjamin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Bενιαμιν</font> &lt; בנימן - <font face=\"Georgia\">Βενιαμ(ε)ίν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Philippiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G959":"<h1>Bernike</h1>\n<p>Strong n° 959 <i>Prononciation [ber-nee'-kay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bérénice (Angl. Bernice) = « remportant la victoire, victorieuse »\n<ol><li>fille aînée d'Hérode Agrippa I. (<a class=\"ref\" data-r=\"ACT12.1\">Actes 12.1</a>) mariée à son oncle Hérode, roi de Chalcis, qui mourut peu après. Elle vécut irrégulièrement avec son propre frère Agrippa II, cause d'un grand scandale. C'est avec lui qu'elle était présente chez Festus lors de la défense de Paul. Elle devint plus tard la maîtresse de Vespasien, puis de Titus.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βερνίκη, ης (ἡ)</b> <i>c</i>. Βερενίκη, <i>v. d’Épire,</i> APP.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βερνικη - Βερνίκη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G960":"<h1>Beroia</h1>\n<p>Strong n° 960 <i>Prononciation [ber'-oy-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bérée (Angl. Berea) = « bien arrosée »\n<ol><li>ville de Macédoine, proche de Pella, au pied du Mont Bermius</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βέροια, ας (ἡ)</b> Bérœa :<br><b>      1</b> <i>n. de f. myth</i>. NONN. <i>D. 41, 151, 155 ;</i><br><b>      2 Β</b>. <i>ou</i> <b>Βέρροια (ἡ)</b> Bérœa <i>ou</i> Berrœa, <i>v. de Macédoine (auj</i>. Véria), THC. <i>1, 61 ; etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Épq</i>. Βεροίη, ANTH. <i>7, 390</i>.<br><span><b>Étym</b>. <i>Cf</i>. Βερόη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βεροια - Βέροια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G961":"<h1>Beroiaios</h1>\n<p>Strong n° 961 <i>Prononciation [ber-oy-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un habitant de Bérée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βεροιαῖος, ου (ὁ)</b> de Bérœa, ARR. NT.<br><span><b>Étym</b>. Βέροια.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βεροιαιος - Βεροιαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G962":"<h1>Bethabara</h1>\n<p>Strong n° 962 <i>Prononciation [bay-thab-ar-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Béthanie (Angl. Bethabara) = « maison du gué »\n<ol><li>un lieu au delà du Jourdain, où Jean baptisait. Ce lieu peut correspondre à Bethabara (gué d'Abara), l'ancien gué du Jourdain sur la route de Galaad</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βηθαβαρα</font> &lt; בית־היני - <font face=\"Georgia\">Βηθαβαρά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G963":"<h1>Bethania</h1>\n<p>Strong n° 963 <i>Prononciation [bay-than-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Béthanie (Angl. Bethany) = « maison des dattes non mûres » = « maison de l'affligé »\n<ol>\n<li>village du Mont des Oliviers, à environ 3 km de Jérusalem, sur ou près de la route de Jéricho</li>\n<li>ville ou village sur la rive est du Jourdain, où Jean baptisait</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βηθανία, ας (ἡ)</b> Bèthanie, <i>village de Palestine, près de Jérusalem,</i> NT.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βηθανια</font> &lt; בית־היני - <font face=\"Georgia\">Βηθανία</font>\n<br><br>origine : Araméen</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (4)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G964":"<h1>Bethesda</h1>\n<p>Strong n° 964 <i>Prononciation [bay-thes-dah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Béthesda (Angl. Bethesda) = « maison de miséricorde »\n<ol><li>nom d'une piscine près de la porte des brebis à Jérusalem, dont les eaux avaient des pouvoirs curatifs</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βηθεσδα</font> &lt; בית־חסדא - <font face=\"Georgia\">Βηθεσδά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G965":"<h1>Bethleem</h1>\n<p>Strong n° 965 <i>Prononciation [bayth-leh-em']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bethléhem (Angl. Bethlehem) = « maison du pain »\n<ol><li>village à environ 10 km au sud de Jérusalem</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βηθλεέμ (τὸ)</b> JOS. <i>8, 10, 1 ;</i> ANTH. <i>1, 42 ;</i> <b>Βηθλεέμη, ης (ἡ)</b> JOS. <i>6, 8, 1 ; 7, 1, 3 ;</i> <b>Βηθλέεμα, ων (τὰ)</b> JOS. <i>5, 7, 13 ;</i> <b>Βήθλεμα, ῶν (τὰ)</b> JOS. <i>5, 2, 8 ;</i> ANTH. <i>8, 21,</i> Bethléem, <i>brg de Judée</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βηθλεεμ</font> &lt; בית־לחם - <font face=\"Georgia\">Βηθλέεμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G966":"<h1>Bethsaida</h1>\n<p>Strong n° 966 <i>Prononciation [bayth-sahee-dah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bethsaïda (Angl. Bethsaida) = « maison de la pêche »\n<ol>\n<li>petit village de pêcheurs sur la côte ouest du Lac de Génésareth, demeure d'André, Pierre, Philippe et Jean</li>\n<li>village de la côte est du Lac de Génésareth, proche du lieu où le Jourdain débouche</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βηθσαϊδά, ᾶς (ἡ)</b> JOS. NT. <i>ou</i> Βηθσαϊδά, <i>indécl</i>. NT. Bèthsaïda, <i>v. de Galilée</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βηθσαιδα</font> &lt; בית־צידה - <font face=\"Georgia\">Βηθσαϊδά</font>\n<br><br>Voir définition 6719</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G967":"<h1>Bethphage</h1>\n<p>Strong n° 967 <i>Prononciation [bayth-fag-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bethphagé (Angl. Bethphage) = « maison des figues pas mûres »\n<ol><li>nom d'un hameau entre Jéricho et Jérusalem, vers Béthanie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βηθφαγῆ</b>, Bèthphagè, <i>lieu près de Jérusalem,</i> NT. <i>Matth. 21, 1, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βηθφαγη</font> &lt; בתי־פגי - <font face=\"Georgia\">Βηθφαγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G968":"<h1>bema</h1>\n<p>Strong n° 968 <i>Prononciation [bay'-ma]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une marche, un pas, l'espace couvert par un pied</li>\n<li>un lieu élevé où on monte par des marches\n<ol type=\"a\">\n<li>une plate-forme, une tribune\n<ol>\n<li>du siège officiel d'un juge</li>\n<li>du trône du jugement de Christ</li>\n<li>structure construite par Hérode à Césarée, pour voir les jeux et faire des discours au peuple</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βῆμα, ατος (τὸ) :<br>   I</b> pas :<br><b>      1</b> pas, enjambée, HH. <i>Merc. 222, 345 ;</i> HDT. TRAG. ; βῆμα τοσόνδε, AR. <i>Eq. 76,</i> une si grande enjambée ; κατὰ βῆμα πορεύεσθαι, XÉN. aller pas à pas ;<br><b>      2</b> pas, <i>mesure de longueur de 10</i> παλαισταί, <i>environ 2 ½ pieds,</i> HÉRON ;<br><b>      3</b> escorte, conduite, <i>au sens de</i> πομπή, SOPH. <i>El. 164 ;</i><br><b>   II</b> surface élevée sur laquelle on pose le pied :<br><b>      1</b> pas, degré, marche, SOPH. <i>O.C. 193 ;</i><br><b>      2</b> plate-forme, estrade <i>ou</i> tribune, THC. <i>2, 34 ;</i> ORAT. ; ἐπὶ τὸ β. ἀναϐαίνειν, DÉM. monter à la tribune ; οἱ ἀπὸ τοῦ βήματος, PLUT. les gens de la tribune, les orateurs, <i>en parl. des deux plates-formes où se tenaient, dans les cours de justice, le demandeur et le défendeur,</i> DÉM. <i>1176, 2 ;</i> ESCHN. <i>83, 32, etc. ; postér</i>. plate-forme où est dressé l’autel dans une église, <i>d’où</i> autel, NAZ. <i>2, 561</i> d, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. βᾶμα, PD. <i>P. 3, 75</i>.<br><span><b>Étym</b>. βαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βημα - βῆμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (1)</li>\n<li>Actes (8)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G969":"<h1>berullos</h1>\n<p>Strong n° 969 <i>Prononciation [bay'-rool-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>minéral de roche, d'ordinaire vert ou vert bleuâtre, apparenté à l'émeraude</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βήρυλλος, ου (ἡ)</b> béryl, pierre précieuse d’un vert de mer, DP. <i>1012</i> ANTH. <i>9, 544 ;</i> LUC. <i>V.H. 2, 11, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βηρυλλος - βήρυλλος</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G970":"<h1>bia</h1>\n<p>Strong n° 970 <i>Prononciation [bee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>force, que ce soit du corps ou de l'esprit</li>\n<li>force dans une action violente, violence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βία, ας (ἡ)</b> <span>[ῐ]</span> force, <i>d’où :</i><br><b>      1</b> force vitale, ἀφαιρεῖσθαι βίας χαλκῷ, OD. <i>22, 219,</i> trancher la vie par le fer ;<br><b>      2</b> <i>p. ext</i>. force du corps, vigueur, <i>en parl. de l’homme et des animaux,</i> HOM. <i>etc. ; joint à</i> κάρτος, OD. <i>4, 415 ; 6, 197, etc. ; à</i> χεῖρες, IL. <i>3, 431 ;</i> OD. <i>12, 246, etc. ; par périphr. en parl. d’hommes forts et courageux :</i> βίη (<i>ion</i>.) Διομήδεος, IL. <i>5, 781, etc. ;</i> βία Τυδέως, ESCHL. <i>Sept. 571, etc.,</i> la force de Diomède, de Tydée, <i>etc. càd</i>. le vaillant Diomède, le vaillant Tydée, <i>etc. ; avec un adj</i>. βίη Ἐτεοκληείη, IL. <i>4, 386 ;</i> β. Ἡρακληείη, IL. <i>5, 638, etc</i>. le valeureux Étéocle, le robuste Hèraklès, <i>etc. ; en parl. de choses (force du vent, etc</i>.) IL. <i>16, 213 ; 23, 713 ; etc. ; puissance d’un engin de tir,</i> HÉRON ; <i>rar. en parl. de l’intelligence,</i> IL. <i>3, 45 ;</i><br><b>      3</b> emploi de la force, violence, HOM. <i>etc. ;</i> βίᾳ τινός, ATT. (ESCHL. <i>Sept. 746 ;</i> THC. <i>1, 43, etc</i>.), en dépit de qqn, malgré qqn ; <i>adv</i>., βίᾳ, ESCHL. <i>Pr. 74, etc. ; ion</i>. βίῃ, IL. <i>12, 341, etc. ;</i> OD. <i>15, 231, etc. ;</i> HDT. <i>6, 5, etc. ;</i> βίηφι, OD. <i>1, 403, etc</i>. par force, de force ; <i>p. opp. à</i> ἔπει, IL. <i>15, 106 ; de même</i> πρὸς βίαν, ESCHL. <i>Pr. 208 ;</i> SOPH. <i>O.R. 805, etc. ;</i> ἐκ βίας, SOPH. <i>Ph. 563, etc. ;</i> ὑπὸ βίας, PLAT. ; ὑπὸ βίης, HDT. <i>6, 107 ;</i> διὰ βίας, PLAT. ; ἀπὸ βίας, DS. <i>20, 51 ; avec idée de colère, de mauvais traitement,</i> SOPH. <i>Aj. 1334 ; joint à</i> ὕϐρις, OD. <i>15, 329 ; surt. au plur</i>. IL. <i>5, 521 ;</i> OD. <i>3, 216 ;</i> βίας γραφή, PLUT. accusation de violence.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. βίη, HOM. HDT. <i>ll. cc. Dat. épq</i>. βίηφι, OD. <i>l. c. ;</i> THCR. <i>Idyl. 25, 138</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>ei-, conquérir, forcer ; <i>cf. sscr</i>. jáyati.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βια - βία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – force, puissance, pouvoir souvent oppressif s'exerçant par des actes de violence\n<br><br> - puissance, capacité naturelle, générale et inhérente\n<br><br> - action, efficacité, pouvoir dans l'exercice, pouvoir opérant  – d'abord liberté d'action ; donc autorité – soit un pouvoir qui a été délégué, ou un pouvoir sans restriction, arbitraire\n<br><br> – force, vertu, puissance (spécialement physique), comme reçue en don\n<br><br> – puissance, force souveraine, le pouvoir manifesté ; – dans le NT il s'agit surtout de la force et du pouvoir de Dieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (4)</li>\n</ul>\n</td></tr>\n</table>","G971":"<h1>biazo</h1>\n<p>Strong n° 971 <i>Prononciation [bee-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>employer la force, appliquer la force</li>\n<li>forcer, infliger de la violence, violenter, contraindre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βιάζω</b> <span>[ῐ]</span> (<i>seul. prés., impf</i>. ἐϐίαζον, <i>ao</i>. ἐϐίασα ; <i>v. ci-dessous</i>) :<br><b>      1</b> user de force <i>ou</i> de violence, <i>abs</i>. HPC. <i>1016</i> h ; β. τινά, OD. <i>12, 297,</i> faire violence à qqn ; <i>au pass</i>. être l’objet de violence, SOPH. <i>Ant. 66, etc. ;</i><br><b>      2</b> <i>p. suite,</i> soumettre par la force : βελέεσσι βιάζεσθαι, IL. <i>11, 589 ; 15, 727,</i> être dompté par la force des traits ; νόσῳ, AR. <i>fr. 91,</i> par la maladie ;<br><b>      3</b> <i>p. ext</i>. forcer, contraindre ; <i>avec l’inf</i>. forcer à, contraindre à, AR. <i>Th. 890 ; abs</i>. βιάζεσθαι, être forcé, être contraint par la force : ὑπό τινος, ANT. <i>128, 32,</i> par qqn ; <i>abs</i>. SOPH. <i>El. 575 ;</i> THC. <i>4, 44, etc. ; p. opp. à</i> συγχωρεῖν, DÉM. <i>286, 26 ; joint à</i> ἄκων, DÉM. <i>69, 14 ; en parl. de choses,</i> τὸ βεϐιασμένον, ARSTT. <i>Metaph. 12, 7, 24,</i> ce qui est le résultat d’une contrainte, ce qui est obtenu par la force ; βεϐιασμένα σχήματα, DH. <i>Thuc. 33,</i> figures de langage forcées ;<br><b><i>Moy</i>. βιάζομαι</b> <span>(<i>f</i>. βιάσομαι, <i>ao</i>. ἐϐιασάμην ; <i>pf</i>. βεϐίασμαι)</span><br><b>   I <i>intr</i>.<br>      1</b> user de violence, <i>abs</i>. ESCHL. <i>Pr. 1010, etc. ; p. opp. à</i> δικάζεσθαι, THC. <i>1, 77 ;</i> β. ἐς τὸ ἔξω, THC. <i>7, 69 ; ou</i> β. εἴσω, XÉN. <i>Cyr. 3, 3, 69,</i> sortir <i>ou</i> entrer de force ; β. διὰ τῶν φυλάκων, THC. <i>7, 83,</i> s’ouvrir de force un chemin à travers les gardes ; <i>avec un inf</i>. β. πρὸς τὸν λόφον ἐλθεῖν, THC. <i>7, 79,</i> s’ouvrir de force un chemin vers la colline ; <i>au participe et joint à un verbe :</i> ἵνα βιασάμενοι ἐκπλεύσωσι, THC. <i>7, 67,</i> afin qu’ils s’ouvrent un passage de force et s’échappent sur leurs vaisseaux ;<br><b>      2</b> devenir violent, <i>en parl. de choses, d’une famine, d’un mal, etc</i>. HDT. <i>1, 94 ;</i><br><b>   II <i>tr.</i></b> violenter, <i>d’où :</i><br><b>      1</b> presser avec force, maltraiter, traiter avec violence <i>ou</i> dureté : τινα, IL. <i>22, 229 ;</i> OD. <i>9, 410 ;</i> PD. ATT. qqn ; β. ἑαυτόν, PLAT. <i>Phæd. 61</i> c, <i>etc</i>. user de violence envers soi-même, <i>càd</i>. se tuer ; <i>p. opp. à</i> πείθειν, LYS. <i>94, 91 ;</i><br><b>      2</b> écarter <i>ou</i> repousser par la force : ναῦς, THC. ; πολεμίους, XÉN. des vaisseaux, l’ennemi ; <i>fig</i>. β. νόμους, THC. <i>8, 53,</i> faire violence aux lois ;<br><b>      3</b> contraindre par la force : β. τινα, ATT. contraindre qqn ; β. τινα <i>avec l’inf</i>. forcer qqn à (faire qqe ch.), XÉN. <i>An. 1, 3, 1, etc. ;</i><br><b>      4</b> se procurer par la force : τι, XÉN. <i>Hell. 5, 3, 12,</i> qqe ch. ; ἀπόϐασιν, THC. <i>4, 11,</i> opérer de force un débarquement ; ἔκπλουν, THC. <i>7, 72,</i> forcer la sortie d’un port, <i>en parl. de navires bloqués ;</i><br><b>      5</b> soutenir avec force (une opinion) ; <i>avec un inf</i>. soutenir avec force que, PLAT. <i>Soph. 241</i> d, <i>246</i> b ; <i>abs</i>. persister dans une opinion <i>ou</i> dans une affirmation, DÉM. <i>580, 16</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. rare, seul. prés. ind. 2 pl</i>. βιάζετε, OD. <i>12, 297. Impf</i>. ἐϐίαζον, HPC. <i>l. c. Ao</i>. ἐϐίασα, ALC. (<i>Com. fr. 2, 833</i>) ; SOPATER (<i>W. 8, 107). — Pass. prés</i>. IL. <i>11, 589 ;</i> ATT. (THC. <i>4, 10 ;</i> XÉN. <i>Conv. 2, 26, etc.). Impf</i>. ἐϐιαζόμην, IL. <i>16, 102 ;</i> THC. <i>5, 3. Fut. réc</i>. βιασθήσομαι, CHARIT. <i>2, 8 ;</i> PAUS. <i>6, 5, 9. Fut. moy. au sens pass. 3 sg</i>. βιᾶται, PLAT. <i>Tim. 63</i> c (<i>sel. Veitch ; mais v</i>. βιάω). <i>Ao</i>. ἐϐιάσθην, PD. <i>N. 9, 14 ;</i> ATT. (SOPH. <i>El. 575 ;</i> THC. <i>4, 44 ;</i> XÉN. <i>Mem. 1, 2, 10 ; etc.). Pf</i>. βεϐίασμαι, XÉN. <i>Hier. 2, 12 ; Hell. 5, 2, 23 ;</i> ARSTT. <i>Metaph. 12, 7, 24 ; etc. — Moy. prés</i>. βιάζομαι, IL. <i>22, 229 ;</i> THGN. <i>547,</i> HDT. <i>9, 41 ;</i> ATT. (ESCHL. <i>Pr. 1010 ;</i> SOPH. <i>Ant. 663 ;</i> AR. <i>Lys. 226 ;</i> THC. <i>4, 9, etc.). Impf</i>. ἐϐιαζόμην, AR. <i>Lys. 396 ;</i> XÉN. <i>An. 1, 3, 1. Fut</i>. βιάσομαι, AR. <i>Pl. 1092 ;</i> PLAT. DÉM. <i>etc. ; p.-ê. 3 sg. contracte</i> βιᾶται (<i>v. ci-dessus au Pass.). Ao</i>. ἐϐιασάμην, ATT. (THC. <i>3, 55, etc</i>.) ; <i>poét</i>. βιασσάμην, OPP. <i>C. 3, 157. Pf</i>. βεϐίασμαι, DÉM. <i>405, 21 ;</i> DC. <i>46, 45</i>.<br><span><b>Étym</b>. βία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιαζω - βιάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G972":"<h1>biaios</h1>\n<p>Strong n° 972 <i>Prononciation [bee'-ah-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>violent, forcé, impétueux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βίαιος, α</b> <i>ou</i> <b>ος, ον</b> <span>[ῐ]</span><br><b>   I</b> <i>act</i>. violent, <i>en parl. des Génies de la mort,</i> HH. <i>7, 17 ; en parl. de pers</i>. THC. <i>1, 40 ; 3, 36 ;</i> HERMOG. <i>1, 44 Walz ; d’ord. en parl. de choses :</i> ἔργα βίαια, OD. <i>2, 236,</i> actes de violence ; β. θάνατος, HDT. <i>7, 170 ;</i> PLAT. <i>etc</i>. mort violente ; τὰ βίαια, PLAT. <i>Leg. 914</i> e ; <i>934</i> c ; DÉM. <i>976, 7,</i> actes de violence, violences ; <i>p. anal. en parl. des forces de la nature (vent, feu, etc</i>.) PAUS. <i>10, 17, 11,</i> PHIL. <i>1, 470, etc. ; adv</i>. βίαια, ESCHL. <i>Suppl. 821 ;</i> πρὸς τὸ βίαιον, ESCHL. <i>Ag. 130 ;</i> ἐκ τοῦ βιαίου, DH. <i>10, 36,</i> de force ;<br><b>   II</b> <i>pass</i>. forcé, contraint, <i>càd. :</i><br><b>      1</b> non volontaire, <i>p. opp. à</i> ἑκούσιος, PLAT. <i>Rsp. 603</i> c ;<br><b>      2</b> non naturel, <i>p. opp. à</i> φύσει, <i>adv</i>., PLAT. <i>Tim. 64</i> d ; ARSTT. <i>Nic. 1, 5, 8 ;</i> β. τροφή, ARSTT. <i>Pol. 8, 4, 7,</i> nourriture forcée, <i>en parl. du régime de vie des athlètes ;</i><br><b>      3</b> forcé par compression, <i>d’où</i> raide, rigide, <i>en parl. d’un mécanisme,</i> HÉRON.<br><span>•<i> Cp</i>. βιαιότερος, XÉN. <i>Hell. 2, 4, 14</i>. <i>• Sup</i>. βιαιότατος, THC. <i>3, 36</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. βιαία, XÉN. <i>Hell. 2, 3, 19</i>.<br><span><b>Étym</b>. βία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιαιος - βίαιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G973":"<h1>biastes</h1>\n<p>Strong n° 973 <i>Prononciation [bee-as-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fort, énergique</li>\n<li>utilisant la force, violent, homme violent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βιαστής, οῦ (ὁ) :<br>      1</b> qui use de violence, NT. <i>Matth. 11, 12 ; cf</i>. POLÉM. ADAM. ;<br><b>      2</b> qui prend de force, ravisseur, NAZ.<br><span><b>Étym</b>. βιάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιαστης - βιαστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G974":"<h1>bibliaridion</h1>\n<p>Strong n° 974 <i>Prononciation [bib-lee-ar-id'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un petit livre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βιϐλαρίδιον, ου (τὸ)</b> <span>[ᾰ]</span> <i>dim. de</i> βιϐλάριον NT. <i>Apoc. 10, 2, 8, 9, 10</i>.<br>\n<b>βιϐλάριον, </b><b>ου (τὸ)</b> <span>[ᾰ]</span> petit livre, ANTH. <i>11, 78</i>.<br><span><b>Étym</b>. <i>dim. de</i> .</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιβλιαριδιον - βιβλαρίδιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G975":"<h1>biblion</h1>\n<p>Strong n° 975 <i>Prononciation [bib-lee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un petit livre, un rouleau, un document écrit, un acte</li>\n<li>une feuille sur laquelle quelque chose a été écrit\n<ol type=\"a\">\n<li>un billet (une lettre) de divorce</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βιϐλίον, ου (τὸ) :<br>      1</b> papier à écrire, HDT. <i>1, 125 ; 3, 42 ;</i> PLUT. <i>Lys. 19 ; d’où</i> lettre, HDT. <i>5, 14 ;</i> SPT. <i>2Reg. 11, 14 ; 1 Macc. 1, 44 ;</i><br><b>      2</b> <i>p. anal</i>. tablette à écrire, SPT. <i>Tob. 7, 14 ;</i><br><b>      3</b> livre, ARSTT. <i>Plant. 2, 2, 1 ;</i> τὰ βιϐλία, SPT. <i>Sir. prol. ; 1 Macc. 12, 9,</i> les livres saints ; <i>d’où</i> division d’un ouvrage, livre, DIOSC. <i>2 Proœm. ; au plur</i>. collection de livres, bibliothèque, D. CHR. <i>2, 104</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pour ce mot, comme pour</i> βίϐλος, βιϐλιοθήκη, <i>l’écriture par</i> ι <i>est régulière dans les inscript. att. jusque dans le 2<sup>e</sup> siècle av. J.C. ; à partir du 1<sup>er</sup> siècle, l’écriture</i> βυϐλίον <i>devient dominante ; v. Meisterh. p. 22, § 13, 4</i>.<br><span><b>Étym</b>. βίϐλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιβλιον - βιβλίον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 28 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>Galates (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (21)</li>\n</ul>\n</td></tr>\n</table>","G976":"<h1>biblos</h1>\n<p>Strong n° 976 <i>Prononciation [bib'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un livre écrit, un rouleau</li>\n<li>le livre de vie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βίϐλος, ου (ἡ) :<br>      1</b> écorce intérieure <i>ou</i> moelle du papyrus, <i>d’où</i> écorce <i>en gén</i>. PLAT. <i>Pol. 288</i> e ;<br><b>      2</b> écrit, livre, ESCHL. <i>Suppl. 947 ;</i> DÉM. <i>313, 13 ; part</i>. division d’un ouvrage, POL. <i>4, 87, 12 ;</i> DS. <i>1, 4 ; en parl. des livres de l’Histoire d’Hérodote,</i> LUC. <i>Her. 1</i>.<br><span><b>Étym</b>. <i>Cf</i>. βύϐλος <i>et</i> βιϐλίον, <i>fin</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιβλος - βίβλος</font>\n<br><br>racine primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>Philippiens (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G977":"<h1>bibrosko</h1>\n<p>Strong n° 977 <i>Prononciation [bib-ro'-sko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>manger avec avidité, dévorer, engloutir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βιϐρώσκω</b> <span>(<i>f</i>. βρώσομαι, <i>ao.2</i> ἔϐρων, <i>pf</i>. βέϐρωκα ; <i>pass. f</i>. βρωθήσομαι, <i>ao</i>. ἐϐρώθην, <i>pf</i>. βέϐρωμαι, <i>f. ant</i>. βεϐρώσομαι)</span> dévorer, manger avec avidité : τι, IL. <i>22, 94,</i> qqe ch. ; τινός, OD. <i>22, 403 ;</i> AR. <i>Vesp. 462,</i> une part de qqe ch., manger avidement de qqe ch. ; <i>fig</i>. dévorer <i>ou</i> engloutir (une fortune), OD. <i>2, 203</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. βρώξω, LYC. <i>678 (dout. p</i>. βρύξω). <i>Fut. moy</i>. βρώσομαι, SIB. <i>7, 157 ;</i> PHILSTR. <i>129. Ao</i>. ἔϐρωξα, ANTH. <i>11, 271 (dout. p</i>. ἔϐροξα). <i>Ao.2 épq</i>. ἔϐρων, CALL. <i>Jov. 49. Pf. opt. 2 sg. épq</i>. βεϐρώθοις, IL. <i>4, 35 ; part. poét</i>. βεϐρώς, SOPH. <i>Ant. 1022</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>erh₃-, dévorer ; <i>cf</i>. βορά, βρῶμα, <i>lat</i>. vŏrō, <i>sscr</i>. gīrṇá-, dévoré.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιβρωσκω - βιβρώσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G978":"<h1>Bithunia</h1>\n<p>Strong n° 978 <i>Prononciation [bee-thoo-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bithynie (Angl. Bithynia) = « une précipitation violente »\n<ol><li>province Romaine d'Asie Mineure, bordée par la Mer Noire, la Phrygie, la Galatie, la Paphlagonie, la Mysie, la Propontide. Nicée, où eut lieu un concile, en est une des villes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βιθυνία, ας (ἡ)</b> <span>[ῑῡ]</span> Bithynie, <i>province d’Asie Mineure,</i> ARSTT. STR. PLUT. <i>etc</i>.<br><span><b>Étym</b>. Βιθυνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βιθυνια - Βιθυνία</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G979":"<h1>bios</h1>\n<p>Strong n° 979 <i>Prononciation [bee'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vie\n<ol type=\"a\">\n<li>la vie dans son sens le plus large\n<ol>\n<li>la période ou le cours de la vie</li>\n</ol>\n</li>\n<li>ce par quoi la vie est assurée, ressources, richesses, biens.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βίος, ου (ὁ)</b> <span>[ῐ]</span><br><b>   I</b> vie, <i>càd. :</i><br><b>      1</b> la vie en soi, l’existence, OD. <i>15, 491 ; 18, 254 ; 19, 127 ;</i> PD. TRAG. ; <i>d’ordin. en parl. de la vie humaine (rar. en parl. d’animaux ou d’insectes,</i> XÉN. <i>Mem. 3, 11, 6 ;</i> ANTH. <i>11, 397</i>) ; αἰὼν βίοιο, HÉS. <i>fr. 172, 1, Göttling</i> le temps de la vie ; ὁδὸς βίου, ISOCR. <i>2</i> a, le chemin de la vie ; ὁ καθ' ἡμέραν βίος, SOPH. <i>O.C. 1364 ;</i> DH. <i>6, 92,</i> la vie de chaque jour ; τέρμα βίου, SOPH. <i>O.R. 1530,</i> le terme de la vie ; ζώειν ἀγαθὸν βίον, OD. <i>15, 491,</i> vivre d’une vie heureuse ; λαγὼ βίον ζῆν, DÉM. <i>314, 21,</i> vivre une vie de lièvre (toujours tremblant et craintif) ; βίον διάγειν, AR. <i>Pax 439,</i> PLAT. <i>Rsp. 372</i> d, passer sa vie ; βίον διέρχεσθαι, PD. <i>I. 4, 7 ;</i> PLAT. <i>Rsp. 365</i> b, <i>367</i> e, arriver au terme de la vie ; βίον διατελεῖν, ISOCR. <i>125</i> b ; τελευτᾶν, ISOCR. <i>57</i> d, achever sa vie ; τὸν μακρὸν βίον τείνειν, ESCHL. <i>Pr. 537,</i> prolonger longtemps sa vie ; <i>au plur</i>. τίνες καὶ πόσοι εἰσὶ βίοι ; PLAT. <i>Leg. 733</i> d, quelles sortes et quel nombre de vies y a-t-il ? <i>cf</i>. ARSTT. <i>Nic. 1, 5, 3 ;</i> POL. <i>1, 8, 4, etc. ; poét. au plur. au sens du sg</i>. ESCHL. <i>fr. 41 ;</i> MÉN. <i>etc. ;</i><br><b>      2</b> temps de la vie, durée de la vie, HDT. <i>6, 109 ;</i> PLAT. <i>Phædr. 242</i> a ;<br><b>      3</b> condition de vie, genre de vie : θαλάττιος βίος, ANTIPH. (<i>Bkk. 30</i>) vie qu’on passe sur mer, vie de marin ; β. πολιτικός, ARSTT. <i>Nic. 1, 5,</i> vie mêlée aux affaires publiques ; <i>cf</i>. PLAT. <i>Leg. 733</i> d, <i>etc. ;</i><br><b>      4</b> <i>p. ext. c</i>. ζωή, souffle de vie : βίον ἐκπνεῖν, ESCHL. <i>Ag. 1517, ou</i> ἀποψύχειν, SOPH. <i>Aj. 1031,</i> exhaler le souffle ; νοσφίζειν τινὰ βίου, SOPH. <i>Ph. 1427,</i> priver qqn de la vie ; <i>pléonast</i>. βίος ζωῆς, PLAT. <i>Epin. 982</i> a, le souffle de la vie ;<br><b>   II</b> moyen de vivre, moyens d’existence, ressources pour vivre, HÉS. <i>O. 31 ;</i> β. πολύς, EUR. <i>Suppl. 861 ; ou</i> ὀλίγος, AR. <i>Pl. 751,</i> ressources pour vivre abondantes <i>ou</i> modiques ; βίον ἔχειν, HÉS. <i>O. 42,</i> avoir des moyens d’existence ; βίον ἔχειν ἀπό τινος, XÉN. <i>Œc. 6, 11 ;</i> PLUT. <i>etc</i>. vivre de qqe ch. (<i>de l’agriculture, etc</i>.) ; βίον ποιεῖσθαι, THC. <i>1, 5 ;</i> συλλέγεσθαι, PLAT. <i>Leg. 936</i> b ; κτᾶσθαι, EUR. <i>Suppl. 450,</i> se procurer, amasser, acquérir des ressources pour vivre ; βίον πορίζειν τινί, AR. <i>Vesp. 706,</i> procurer à qqn des moyens d’existence ; ἀποστερεῖν τὸν βίον, SOPH. <i>Ph. 931,</i> enlever (à qqn) le moyen de vivre, <i>en parl. de l’arc et des flèches dérobés à Philoctète ; en parl. de la nourriture que se procurent les animaux,</i> XÉN. <i>Mem. 3, 11, 6 ;</i><br><b>   III</b> le monde où l’on vit, le monde, les hommes, LUC. <i>D. deor. 13, 1 ;</i> PHIL. <i>1, 70, etc. ;</i> οἱ ἀπὸ τοῦ βίου, SEXT. <i>M. 11, 49,</i> les gens du monde, <i>p. opp. aux philosophes ;</i><br><b>   IV</b> lieu où l’on vit, séjour, résidence, DH. <i>1, 68, 72 ;</i><br><b>   V</b> récit d’une vie, biographie, PHIL. <i>2, 180, etc. ;</i> Βίοι παράλληλοι, Vies mises en parallèle, <i>titre d’un ouvrage célèbre de Plutarque</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>eih₃-, vivre ; <i>cf</i>. ὑγιής, <i>lat</i>. vīvō, vīta, <i>etc. ; sscr</i>. jīvá-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιος - βίος</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – l'existence, ayant la mort comme antithèse, comme achèvement (utilisé aussi pour l'animal)\n<br><br> – la période, les moyens d'existence, la manière de vivre. (utilisé pour l'homme)\n<br><br>Le NT dans son ensemble exalte le , et tend à avilir le .</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (5)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G980":"<h1>bioo</h1>\n<p>Strong n° 980 <i>Prononciation [bee-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dépenser sa vie, vivre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βιόω-ῶ</b> <span>(<i>impf</i>. ἐϐίουν, <i>f</i>. βιώσομαι, <i>ao.1</i> ἐϐίωσα, <i>ao.2 att</i>. ἐϐίων, <i>pf</i>. βεϐίωκα)</span><br><b>      1</b> vivre, IL. <i>8, 429 ;</i> ARSTT. <i>Juv. 12 ;</i><br><b>      2</b> passer sa vie : βίον βιοῦν, PLAT. <i>Lach. 188</i> a, <i>etc</i>. passer sa vie ; βιοῦν καλῶς, εὐσεϐῶς, φαύλως, <i>etc</i>. ATT. (DÉM. <i>601, 2, etc</i>.) vivre honnêtement, pieusement, bassement, <i>etc. ; avec un pron. neutre :</i> ἀπ' αὐτῶν ὧν αὐτὸς βεϐίωκεν ἄρξομαι, DÉM. <i>270, 19,</i> je commencerai par le détail de sa vie ; <i>au pass</i>. τὰ πεπραγμένα καὶ βεϐιωμένα, DÉM. <i>609, 2, 3,</i> ce qu’on a fait et la vie qu’on a menée ; βεϐιωμένος βίος, DÉM. <i>403, 25,</i> la vie qu’on a vécue ; <i>impers</i>. βεϐίωταί μοι, DÉM. <i>617 fin,</i> la vie s’est passée pour moi, j’ai vécu ;<br><b><i>Moy.</i></b> :<br><b>      1 <i>intr.</i></b> passer sa vie, vivre, HDT. <i>2, 177 ;</i> ARSTT. <i>Nic. 10, 9, 11 ;</i><br><b>      2 <i>tr.</i></b> faire vivre, sauver la vie à, <i>acc</i>. OD. <i>8, 468</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. part. ion. plur</i>. βιεῦντες, Ps.-PHOCYL. <i>229. Fut</i>. βιώσομαι, EUR. <i>Alc. 784 ;</i> AR. <i>Eq. 699 ;</i> XÉN. <i>Cyr. 5, 4, 34, etc. ; postér</i>. βιώσω, APP. <i>Civ. 4, 119 ;</i> DL. <i>2, 68 ;</i> LUC. <i>Nav. 26, etc. ; inf. poét</i>. βιωσέμεν, ORPH. <i>Lith. 624. Ao.1</i> ἐϐίωσα, <i>ion</i>. (HDT. <i>1, 163 ; 2, 133 ;</i> HPC.) <i>ou de prose réc</i>. (ARSTT. <i>H.A. 5, 14, 15 ; 7, 4, 20 ;</i> PLUT. <i>Ant. 86 ;</i> LUC. <i>Macr. 8, etc.), rare chez les Att</i>. XÉN. <i>Œc. 4, 18 (vulg</i>.) ; PLAT. <i>Phæd. 113</i> d. <i>Ao.2</i> ἐϐίων, <i>plus us</i>. ISOCR. <i>203</i> c ; IS. <i>38, 14 ; impér. 3 sg</i>. βιώτω, IL. <i>8, 429 ; sbj. 3 sg</i>. βιῷ, PLAT. <i>Leg. 872</i> c ; <i>opt</i>. βιῴην, PLAT. <i>Gorg. 512</i> e, <i>Tim. 89</i> c ; <i>inf</i>. βιῶναι, (<i>au sens du prés. dans Hom</i>. IL. <i>10, 174 ; 15, 511 ;</i> OD. <i>14, 359</i>) ; SOPH. <i>O.R. 1488, etc. ; part</i>. βιούς, HDT. <i>9, 10 ;</i> THC. <i>2, 53, etc. ; fém</i>. βιοῦσα, ANTH. <i>App. 262. — Pass. fut. part</i>. βιωθησόμενος, M. ANT. <i>9, 30. Pf. (v. ci-dessus). — Moy. fut. épq. réc. 2 pl</i>. βώσεσθε (<i>p</i>. βιώσ-), A. RH. <i>1, 685. — Les Att. emploient d’ord., au lieu du prés. et de l’impf. act., les temps correspondants de</i> ζάω. — <i>Sur la forme</i> βιόμεσθα, <i>qqf. rattachée à</i> βιόω, <i>v</i>. *βίομαι.<br><span><b>Étym</b>. βίος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιοω - βιόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G981":"<h1>biosis</h1>\n<p>Strong n° 981 <i>Prononciation [bee'-o-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>manière de vivre et d'agir, ressource</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βίωσις, εως (ἡ)</b> moyens de vivre, ressources, SPT. <i>Sir. prol. ;</i> NT. <i>Ap. 26, 4</i>.<br><span><b>Étym</b>. βιόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιωσις - βίωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G982":"<h1>biotikos</h1>\n<p>Strong n° 982 <i>Prononciation [bee-o-tee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui appartient à la vie et les affaires de cette vie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βιωτικός, ή, όν</b> ; :<br><b>      1</b> qui concerne la vie, qui sert à l’entretien de la vie, POL. <i>4, 73, 8 ;</i> DS. <i>2, 29 ;</i> ἡ βιωτική (<i>s.-e</i>. τέχνη) M. ANT. <i>7, 61,</i> la science de la vie, la morale pratique ; τὰ βιωτικά, la vie, <i>p. opp. aux spéculations de la philosophie,</i> SEXT. <i>P. 2 ;</i> temporel <i>p. opp. à spirituel,</i> NT. <i>Luc. 21, 34 ;</i><br><b>      2</b> qui se procure des moyens de vivre, industrieux pour vivre, ARSTT. <i>H.A. 9, 17, 2</i>.<br><span>•<i> Cp</i>. βιωτικώτερος, CHRYS. <i>1, 144</i> d ; <i>155</i> d ; <i>221</i> d.<br><span><b>Étym</b>. βιόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βιωτικος - βιωτικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G983":"<h1>blaberos</h1>\n<p>Strong n° 983 <i>Prononciation [blab-er-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pernicieux, préjudiciable, nuisible, funeste</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλαϐερός, ά, όν</b> <span>[ᾰ]</span> nuisible, funeste, HH. <i>Merc. 36 dout. ;</i> HÉS. <i>O. 363 ;</i> XÉN. <i>Cyr. 8, 8, 7 ; etc</i>.<br><span>•<i> Sup</i>. -ώτατος, PLAT. <i>Phædr. 239</i> b.<br><span><b>Étym</b>. βλάπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλαβερος - βλαβερός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G984":"<h1>blapto</h1>\n<p>Strong n° 984 <i>Prononciation [blap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire mal, nuire à, blesser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλάπτω</b> <span>(<i>impf</i>. ἔϐλαπτον, <i>f</i>. βλάψω, <i>ao</i>. ἔϐλαψα, <i>pf</i>. βέϐλαφα <span>[ᾰφ]</span>; <i>pass. f</i>. βλαϐήσομαι <span>[ᾰ]</span>, <i>ao.1</i> ἐϐλάφθην, <i>ao.2</i> ἐϐλάϐην <span>[ᾰ]</span>, <i>pf</i>. βέϐλαμμαι)</span><br><b>   I. 1</b> léser, endommager : ἵππους, IL. <i>23, 571,</i> blesser des chevaux ; <i>au pass</i>. éprouver un accident fâcheux, IL. <i>23, 545 ; etc. ;</i><br><b>      2</b> gêner, embarrasser, <i>à peu près au sens de</i> ἐμποδίζειν : βλ. τινα, OD. <i>13, 22,</i> gêner qqn ; <i>au pass</i>. être embarrassé, <i>en parl. de chevaux embarrassés (dans des branches de tamaris</i>), IL. <i>6, 39 ; avec un gén</i>. τινὰ βλ. κελεύθου, OD. <i>1, 195,</i> contrarier qqn en l’écartant de sa route ; <i>d’où</i> arrêter : πόδας, IL. <i>13, 782,</i> les pieds (d’Ajax) ; <i>au pass</i>. βλαϐεὶς δρόμων, ESCHL. <i>Ag. 120,</i> arrêté malheureusement dans sa course ;<br><b>      3</b> <i>en parl. de l’esprit,</i> troubler la raison : βλ. φρένας, IL. <i>15, 724 ;</i> τινὰ βλ. φρένας, OD. <i>14, 178 ; d’où abs</i>. βλ. τινά, OD. <i>23, 14,</i> troubler la raison de qqn ; <i>en parl. de l’ivresse,</i> OD. <i>21, 294 ; avec un gén</i>. βλάπτειν νόοιο, THGN. <i>705,</i> troubler la raison ; νόου βεϐλαμμένος, THGN. <i>223,</i> qui a l’esprit troublé ;<br><b>   II</b> <i>postér</i>. faire du tort, nuire :<br><b>      1</b> <i>en gén. :</i> πλείω βλ. τινα, THC. <i>6, 33 ; ou</i> μείζω, PLAT. <i>Ap. 30</i> c, causer à qqn plus de dommages <i>ou</i> de plus grands dommages ; μεγάλα βλάπτεσθαι, XÉN. <i>Cyr. 5, 3, 13,</i> éprouver de grands dommages ; <i>rar. avec le dat</i>. βλ. τινί, ESCHL. <i>Eum. 661,</i> causer du mal à qqn ; <i>au pass</i>. βλάπτεσθαι ὑπό τινος, ATT. éprouver un dommage de la part de qqn ; τὸ βλαϐέν, PLAT. <i>Leg. 933</i> e, tort fait à qqn ;<br><b>      2</b> <i>part</i>. faire tort en trompant, tromper : τινά, IL. <i>22, 15,</i> qqn ;<br><b>      3</b> faire tort en privant de, frustrer de, priver de : βλ. πόλιν τινάς, APP. <i>Civ. 2, 131,</i> priver la ville de certains citoyens ; <i>au pass</i>. APP. <i>Hann. 28 ;</i><br><b>      4</b> <i>en gén</i>. porter atteinte à : ὅρκους, ARSTT. <i>fr. 143,</i> violer des serments ;<br><b><i>Moy.</i></b> (<i>seul. ao. 3 pl. poét</i>. βλάψαντο) faire du mal à, Q. SM. <i>5, 466</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. Impf. poét. 3 sg</i>. βλάπτεν, IL. <i>15, 724. Ao. poét. 3 sg</i>. βλάψε, IL. <i>23, 774. — Pass. fut</i>. βλαϐήσομαι, ISOCR. <i>7</i> b ; PLAT. <i>Gorg. 475</i> d ; <i>Men. 77</i> e ; PLUT. <i>Phil. 3, etc. Ao.1</i> ἐϐλάφθην, IL. <i>6, 39 ; 23, 387 ;</i> THC. <i>4, 73, 87, etc. Ao.2</i> ἐϐλάϐην, ESCHL. <i>Ag. 120 ;</i> THC. <i>1, 141 ;</i> XÉN. <i>Hell. 6, 5, 48 ; 3 pl. épq</i>. ἔϐλαϐεν, IL. <i>23, 461 ou</i> βλάϐεν, IL. <i>23, 545 ;</i> PD. <i>N. 7, 18. Pf. part</i>. βεϐλαμμένος, IL. <i>16, 660, dout. (conj</i>. βεϐλημένος) ; THGN. <i>l. c. Fut. ant</i>. βεϐλάψομαι, HPC. <i>385, 52. — Moy. f</i>. βλάψομαι <i>au sens pass</i>. THC. <i>1, 81 ; 6, 64</i>.<br><span><b>Étym</b>. βλάϐη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλαπτω - βλάπτω</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G985":"<h1>blastano</h1>\n<p>Strong n° 985 <i>Prononciation [blas-tan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pousser, bourgeonner, avoir de nouvelles feuilles</li>\n<li>produire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλαστάνω</b> <span>(<i>impf</i>. ἐϐλάστανον, <i>f</i>. βλαστήσω, <i>ao.1 au sens trans</i>. ἐϐλάστησα, <i>ao.2</i> ἔϐλαστον, <i>pf</i>. βεϐλάστηκα <i>et</i> ἐϐλάστηκα)</span><br><b>      1 <i>intr.</i></b> germer, pousser, croître, <i>en parl. de plantes,</i> ESCHL. <i>Sept. 594 ;</i> SOPH. <i>O.C. 697 ;</i> AR. <i>Nub. 1108 ; Av. 696 ;</i> THC. <i>3, 26 ;</i> XÉN. <i>Œc. 19, 2 ; p. anal. en parl. d’enfants,</i> naître, PD. <i>N. 8, 7 ; d’où en gén. en parl. de pers</i>. être né, être issu : ἐξ ἀρίστοιν, SOPH. <i>Aj. 1305,</i> de nobles parents ; <i>cf</i>. EUR. <i>I.A. 594 ; en parl. de l’île de Rhodes surgissant de la mer,</i> PD. <i>O. 7, 69 ; fig. en parl. de choses abstraites (résolutions, sentiments qui germent dans le cœur, etc</i>.) ESCHL. <i>Sept. 576 ;</i> SOPH. <i>O.C. 611, etc. ;</i><br><b>      2</b> <i>tr. au sens causal,</i> faire germer, faire naître, <i>rar. au prés</i>. HPC. <i>383, 20, ou au fut</i>. TRAG. <i>fr. incert. 269 Wagn. ; d’ord. à l’ao.1,</i> A. RH. <i>1, 1131 ;</i> NONN. <i>D. 36, 356 ;</i> SPT. <i>Gen. 1, 11 ; Num. 18, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. itér. 3 sg</i>. βλαστάνεσκε, SOPH. <i>fr. 491. Ao.1 ion. ou de prose réc</i>. EMPÉD. <i>105 ; 244 Stein ;</i> HPC. ARSTT. THC. <i>etc. Ao.2 poét</i>. βλάστον, PD. <i>O. 7, 69. Pf</i>. βεϐλάστηκα, HPC. PLUT. ; <i>poét</i>. ἐϐλάστηκα, EUP. <i>2-1, 561 Meineke ;</i> EUR. <i>I.A. 595. Pl.q.pf. 3 sg</i>. ἐϐεϐλαστήκει, THC. <i>3, 26 ;</i> LUC. <i>V.H. 1, 31</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλαστανω - βλαστάνω</font>\n<br><br>vient de blastos (une pousse)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G986":"<h1>Blastos</h1>\n<p>Strong n° 986 <i>Prononciation [blas'-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Blaste (Angl. Blastus) = « pousse, rejeton »\n<ol><li>le chambellan de Hérode Agrippa I, préfet</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βλαστος - Βλάστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G987":"<h1>blasphemeo</h1>\n<p>Strong n° 987 <i>Prononciation [blas-fay-meh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parler outrageusement, insulter, calomnier, blasphémer</li>\n<li>être injurié, insulté, raillé</li>\n<li>blasphémer 1) contre le Christ 2) contre les anges 3) contre le Nom de Dieu 4) contre Le Saint-Esprit</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλασφημέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐϐλασφήμησα, <i>pf</i>. βεϐλασφήμηκα)</span><br><b>   I</b> <i>au sens religieux :</i><br><b>      1</b> prononcer des paroles de mauvais augure <i>ou</i> qui ne doivent pas être prononcées pendant un sacrifice, <i>p. opp. à</i> εὐφημέω : βλ. εἰς θεούς, prononcer des paroles impies contre les dieux, PLAT. <i>Rsp. 381</i> e, <i>ou</i> adresser aux dieux des prières inconsidérées, PLAT. <i>2 Alc. 149</i> c ;<br><b>      2</b> <i>abs</i>. blasphémer, SPT. NT. ;<br><b>   II</b> <i>p. ext</i>. tenir de mauvais propos sur, médire de : περί τινος, ISOCR. <i>310</i> b ; DÉM. <i>228, 14 ; 252, 29,</i> de qqn ; κατά τινος, ISOCR. <i>246</i> a, lancer de mauvais propos contre qqn ; <i>avec un double rég</i>. τι εἴς τινα βλ. DÉM. <i>1229, 5,</i> prononcer de mauvaises paroles à l’adresse de qqn ; <i>avec l’acc</i>. βλ. τινα, NT. <i>Luc. 23, 39, etc</i>. diffamer qqn ; <i>au pass</i>. être de la part de qqn l’objet de mauvais propos, NT. <i>1Cor. 10, 30</i>.<br><span><b>Étym</b>. βλάσφημος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλασφημεω - βλασφημέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n34 fois dans 34 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Timothée (2)</li>\n<li>Tite (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (3)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G988":"<h1>blasphemia</h1>\n<p>Strong n° 988 <i>Prononciation [blas-fay-me'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>calomnie, discours injurieux, insulte, outrage, détraction</li>\n<li>discours impie et injurieux envers la divine majesté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλασφημία, ας (ἡ) :<br>   I</b> <i>au sens religieux :</i><br><b>      1</b> parole de mauvais augure <i>ou, en gén.,</i> parole qui ne doit pas être prononcée dans une cérémonie religieuse, <i>p. opp. à</i> εὐφημία, EUR. <i>Ion 1189 ;</i> PLAT. <i>Leg. 800</i> c <i>et d ;</i><br><b>      2</b> parole impie, blasphème, MÉN. <i>fr. inc. 169 Meineke ;</i> τινός, NT. <i>Matth. 12, 31 ;</i> πρός τινα, NT. <i>Apoc. 13, 6,</i> contre qqn ;<br><b>   II</b> <i>en gén</i>. mauvais propos, médisance, calomnie, diffamation, DÉM. <i>141, 2 ; 257, 22 ;</i> ESCHN. <i>24, 4, etc</i>.<br><span><b>Étym</b>. βλάσφημος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλασφημια - βλασφημία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 18 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (4)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G989":"<h1>blasphemos</h1>\n<p>Strong n° 989 <i>Prononciation [blas'-fay-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler en mal, blasphématoire, abusif, discours injurieux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλάσ·φημος, ος, ον :<br>      1</b> <i>au sens religieux, litt</i>. qui prononce des paroles de mauvais augure, <i>part</i>. qui prononce des paroles impies, qui blasphème, SPT. NT. ; <i>subst</i>. ὁ βλ. blasphémateur, SPT. <i>2Macc. 10, 36 ;</i> NT. <i>1Tim. 1, 13, etc. ;</i><br><b>      2</b> <i>en gén</i>. qui tient de mauvais propos, médisant, diffamateur de, <i>gén</i>. PLUT. <i>M. 1100</i> d, <i>etc. ; abs</i>. ARSTT. <i>Pol. 2, 23 ; en parl. des propos eux-mêmes,</i> DÉM. <i>110, 9</i>.<br><span>•<i> Sup</i>. -ότατος, LUC. <i>Alex. 4</i>.<br><span><b>Étym</b>. <i>p.-ê</i>. βλάϐος <i>ou</i> μέλεος, φήμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλασφημος - βλάσφημος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G990":"<h1>blemma</h1>\n<p>Strong n° 990 <i>Prononciation [blem'-mah</i>]</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un regard, un coup d'œil</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλέμμα, ατος (τὸ) :<br>      1</b> regard, EUR. <i>H.f. 306 ;</i> AR. <i>Pl. 1022 ;</i> DÉM. <i>etc. ;</i><br><b>      2</b> <i>au pl</i>. les yeux, ESCHL. <i>fr. 238 ;</i> ANTIPH. (ATH. <i>38</i> b).<br><span><b>Étym</b>. βλέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλεμμα - βλέμμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G991":"<h1>blepo</h1>\n<p>Strong n° 991 <i>Prononciation [blep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>voir, discerner, par l'intermédiaire de l'œil\n<ol type=\"a\">\n<li>posséder la vue</li>\n<li>voir, regarder, apercevoir</li>\n<li>tourner les yeux vers une chose, regarder fixement</li>\n<li>percevoir par les sens, sentir</li>\n<li>découvrir à l'usage, savoir par expérience</li>\n</ol>\n</li>\n<li>métaph : voir avec les yeux de l'esprit\n<ol type=\"a\">\n<li>avoir la compréhension, l'intelligence</li>\n<li>discerner mentalement, découvrir, comprendre</li>\n<li>tourner les pensées ou diriger l'esprit sur une chose, considérer.</li>\n</ol>\n</li>\n<li>dans un sens de lieux géographiques : (montagne, immeuble...) : en considérer chaque face</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βλέπω</b> <span>(<i>impf</i>. ἔϐλεπον, <i>f</i>. βλέψομαι, <i>postér</i>. βλέψω, <i>ao</i>. ἔϐλεψα, <i>pf. inus. ; pf. pass</i>. βέϐλεμμαι)</span><br><b>A</b> voir :<br><b>   I</b> <i>abs</i>. avoir le sens de la vue, jouir de la vue, <i>p. opp. à</i> τυφλός (εἰμι), SOPH. <i>O.R. 302, 348, etc. ;</i> AR. <i>Pl. 15 ;</i> μὴ βλέπειν, SOPH. <i>O.C. 73,</i> être aveugle ; <i>fig</i>. voir avec les yeux de l’esprit ; <i>en parl. d’un devin,</i> SOPH. <i>O.R. 747 ;</i> ὁ βλέπων, SPT. <i>1Reg. 9, 9,</i> le prophète ;<br><b>   II</b> <i>avec un acc</i>. βλ. φάος, ESCHL. <i>Pers. 261, ou</i> φῶς ἡλίου, EUR. <i>Hel. 60,</i> voir la lumière du soleil, <i>càd</i>. être vivant, vivre ; <i>d’où abs</i>. βλέπειν, <i>m. sign</i>. ESCHL. <i>Ag. 677 ;</i> SOPH. <i>Ph. 883, Aj. 962 ; fig. en parl. de choses,</i> ἀληθῆ καὶ βλέποντα, ESCHL. <i>Ch. 844,</i> choses vraies et vivantes, <i>càd</i>. présentes, actuelles ; <i>au pass</i>. ἐξ ἑαυτοῦ βλεπόμενον, SEXT. <i>M. 1, 184,</i> chose évidente de soi-même ;<br><b>B</b> regarder, <i>càd. :</i><br><b>   I</b> diriger ses regards sur <i>ou</i> vers : ἐπί τινι, SOPH. <i>Aj. 345 ;</i> εἴς τινα, DÉM. <i>320, 3,</i> sur <i>ou</i> vers qqn ; εἴς τι, ESCHL. <i>Pers. 802 ;</i> ἐπί τι, THC. <i>7, 71,</i> sur <i>ou</i> vers qqe ch. ; <i>p. anal. avec un suj. de chose :</i> οἰκία πρὸς μεσημϐρίαν βλέπουσα, XÉN. <i>Mem. 3, 8, 9,</i> maison qui regarde le midi ; κάτω οἱ ὀδόντες βλέπουσι, ARSTT. <i>H.A. 2, 5,</i> les dents regardent en bas ; <i>fig. :</i><br><b>      1</b> tourner les yeux vers qqn <i>ou</i> qqe ch. : εἴς τινα, SOPH. <i>Ant. 923 ;</i> εἴς τι, SOPH. <i>Aj. 514,</i> tourner ses regards vers qqn <i>ou</i> qqe ch. (vers les dieux, vers un sauveur, vers un moyen de salut, <i>etc</i>.) ;<br><b>      2</b> avoir les yeux sur, <i>càd</i>. surveiller, veiller sur : τινά, NT. <i>Marc. 13, 9,</i> sur qqn ; ἀπό τινος, NT. <i>Marc. 8, 15,</i> avoir l’œil ouvert pour se garder de qqe ch. ; βλ. ἵνα, NT. <i>1Cor. 16, 10,</i> veiller à ce que ; βλ. μή, NT. <i>2Joh. 8,</i> veiller à ce que… ne ;<br><b>      3</b> avoir en vue : πρός τι, PLAT. <i>Conv. 181</i> b, qqe ch. ; <i>avec l’inf</i>. ὀρχεῖσθαι μόνον βλέποντες, ALEX. (ATH. <i>134</i> c) ne voyant qu’une chose, danser, <i>càd</i>. n’ayant que ce désir ; <i>cf</i>. AR. <i>Ach. 376, Vesp. 847 ; etc. ;</i><br><b>   II</b> avoir un regard (bienveillant, hostile, <i>etc.) avec un adv</i>. πῶς βλέπων ; SOPH. <i>Ph. 110,</i> avec quel regard ? de quel air ? φιλοφρόνως, ἐχθρῶς βλ. πρός τινα, XÉN. <i>Mem. 3, 10, 4, etc</i>. regarder qqn avec bienveillance, d’un air hostile ; <i>avec un adj. ou un participe adv</i>. βλ. σεμνὸν καὶ πεφροντικός, EUR. <i>Alc. 773,</i> regarder d’un air grave et pensif ; βλ. δριμύ, ὀξύ, <i>etc</i>. PLAT. jeter un regard vif, perçant, <i>etc. ; avec un subst</i>. βλ. Ἄρην, AR. <i>Pl. 328,</i> avoir le regard d’Arès, <i>càd</i>. l’air belliqueux ; <i>comiq</i>. βλ. νᾶπυ, AR. <i>Eq. 631, ou</i> κάρδαμα, AR. <i>Vesp. 455,</i> avoir un regard de moutarde <i>ou</i> de cresson, <i>càd</i>. un air dur <i>ou</i> aigre.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. part. fém. dor</i>. βλέποισα, THCR. <i>Idyl. 20, 13. Fut</i>. βλέψομαι, DÉM. <i>799, 21. Fut. réc</i>. βλέψω, SIB. <i>1, 353 ; 8, 207 ;</i> ARSTD. <i>45, 46 ;</i> SPT. <i>Esaï. 6, 9</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλεπω - βλέπω</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Comparer : , \n<br><br> donne la prééminence à l'esprit de discernement,  à une ambiance ou un point particulier.\n<br><br>Comparer : , \n<br><br> est plus pointu que , souvent du sens de « scruter, observer ». « Fixer les yeux (de l'esprit) sur, diriger son attention vers » une chose avec l'intention de l'obtenir, y trouver un intérêt. De là le sens fréquent de « viser à, soigner etc. »</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n133 fois dans 115 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (20)</li>\n<li>Marc (16)</li>\n<li>Luc (17)</li>\n<li>Jean (17)</li>\n<li>Actes (13)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (7)</li>\n<li>2 Corinthiens (7)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (3)</li>\n<li>Hébreux (8)</li>\n<li>Jacques (1)</li>\n<li>2 Jean (1)</li>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G992":"<h1>bleteos</h1>\n<p>Strong n° 992 <i>Prononciation [blay-teh'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui doit être mis ou déposé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>βλητέον</b>, <i>vb. de</i> , NT. <i>Marc. 2, 22</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βλητεος - βλητέος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G993":"<h1>Boanerges</h1>\n<p>Strong n° 993 <i>Prononciation [bo-an-erg-es']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Boanergès (Angl. Boanerges) = « fils du tonnerre »\n<ol><li>un surnom donné à Jacques et Jean, les fils de Zébédée, par le Seigneur. Ce nom semble dénoter leur zèle ardent et destructeur qui ressemblait à un orage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βοανεργες</font> &lt; בני־רגוש - <font face=\"Georgia\">Βοανηργές</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G994":"<h1>boao</h1>\n<p>Strong n° 994 <i>Prononciation [bo-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui crie, ceux qui crient</li>\n<li>crier, s'écrier, parler d'une forte voix, pousser des cris</li>\n<li>crier pour de l'aide, implorer un secours</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βοάω-βοῶ</b> <span>(<i>impf</i>. ἐϐόων, <i>f</i>. βοήσομαι, <i>postér</i>. βοήσω, <i>ao</i>. ἐϐόησα, <i>pf. réc</i>. βεϐόηκα ; <i>pass. ao</i>. ἐϐοήθην, <i>pf</i>. βεϐόημαι)</span> crier, <i>d’où :</i><br><b>   I <i>intr</i>.<br>      1</b> pousser un cri <i>ou</i> des cris ; ὀξὺ βοᾶν, IL. <i>17, 89 ;</i> μακρὰ β. IL. <i>2, 224 ; etc</i>. pousser un cri aigu, un cri prolongé, <i>etc. ;</i> οἱ βοησόμενοι, DÉM. <i>172, 4,</i> les hommes tout prêts à pousser des cris, à faire du bruit (dans l’assemblée) ;<br><b>      2</b> <i>p. ext. avec un suj. de chose, en parl. de tout bruit retentissant (bruit des vagues,</i> IL. <i>14, 394 ;</i> ESCHL. <i>Pr. 431, etc. ; de l’écho,</i> IL. <i>17, 265 ; etc.) ; fig</i>. τὸ πρᾶγμα βοᾷ, AR. <i>Vesp. 921,</i> la chose crie d’elle-même, <i>càd</i>. est évidente ;<br><b>   II <i>tr</i>.<br>      1</b> dire en criant, émettre en criant : βοᾶν βοάν, AR. <i>Nub. 1153,</i> pousser un cri ; β. μέλος, SOPH. <i>Aj. 976,</i> faire résonner un chant ; β. ἄλγος, EUR. <i>Tr. 1310,</i> pousser des cris de douleur ; <i>avec double acc</i>. β. τὸν ὑμέναιον νύμφαν, EUR. <i>Tr. 335,</i> faire résonner le chant de l’hymen en l’honneur de la jeune épousée ;<br><b>      2</b> appeler en criant : τινα, PD. <i>P. 6, 36 ;</i> SOPH. <i>Tr. 212 ;</i> XÉN. <i>Cyr. 7, 2, 5,</i> appeler à grands cris qqn (à son secours) ;<br><b>      3</b> prier à haute voix, invoquer, THCR. <i>Idyl. 17, 60 ;</i><br><b>      4</b> ordonner à haute voix, <i>avec l’inf</i>. SOPH. <i>O.R. 1287 ;</i> EUR. <i>Andr. 298 ; avec un dat. et l’inf</i>. β. τινι ἄγειν τὸ στράτευμα, XÉN. <i>An. 1, 8, 12,</i> crier à un commandant d’amener son corps de troupes ; <i>avec</i> ὅτι, ὡς, <i>etc</i>. XÉN. <i>An. 1, 8, 1 ; etc</i>. crier à qqn de <i>ou</i> que, <i>etc. ; avec un acc</i>. β. τι, EUR. <i>Ph. 1154, etc</i>. crier à qqn d’apporter qqe ch. (<i>du feu, du vin, etc</i>.) ;<br><b>      5</b> proclamer, vanter, πρήγματα βεϐωμένα (<i>v. ci-dessous</i>) ἀνὰ Ἰωνίην, HDT. <i>3, 39,</i> hauts faits célébrés à travers l’Ionie ; <i>cf</i>. HDT. <i>6, 131 ;</i> βοᾶν βίϐλοις, ANTH. <i>7, 438,</i> célébrer par des livres ;<br><b><i>Moy.</i></b> <span>(<i>seul. prés</i>. βοάομαι-βοῶμαι, <i>fut</i>. βοήσομαι, <i>ao</i>. ἐϐοησάμην)</span> crier, EUR. <i>Hel. 1434 ;</i> AR. <i>Vesp. 1228, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. poét</i>. βόων, HÉS. <i>Sc. 243. Impf. itér. 3 sg</i>. βοάασκεν, A. RH. <i>2, 588. Fut</i>. βοήσομαι, ATT. (THC. <i>7, 48 ;</i> PLAT. DÉM. <i>etc</i>.) ; <i>postér</i>. βοήσω, ANTH. <i>7, 32 ; 9, 100 ;</i> A. RH. <i>3, 792. Ao. poét</i>. βόησα (<i>sel. d’autres</i> ἐϐόησα), IL. <i>23, 847. Pf. réc. part. plur</i>. βεϐοηκότες, PHILSTR. <i>V. soph. 561. Moy. prés. inf</i>. βοᾶσθαι, EUR. <i>Hel. 1434 ; part</i>. βοώμενος, AR. <i>Vesp. 1228 ; etc. Fut</i>. βοήσομαι (<i>v. ci-dessus). Ao. 3 sg</i>. βοήσατο, Q. SM. <i>10, 465 (vulg</i>. γοήσατο). — <i>Formes épq. et dialect. : Formes épq. avec extension du radic. : prés. ind. 3 sg</i>. βοάᾳ (<i>p</i>. βοάει) IL. <i>14, 394 ; 3 pl</i>. βοόωσι (<i>p</i>. βοάουσι, βοῶσι) IL. <i>17, 265 ; part</i>. βοόων (<i>p</i>. βοάων, βοῶν) IL. <i>15, 687. Formes épq. ion. et dor. contractes : ao. act</i>. ἔϐωσα, HIPPON. <i>fr. 1 ; d’où impér. 2 sg</i>. βῶσον, CRAT. (<i>Com. fr. 2, 299) ; 3 sg</i>. βωσάτω, AR. <i>Pax 1155 ; inf</i>. βῶσαι, HDT. <i>1, 146 ; part</i>. βώσας, IL. <i>12, 337 ;</i> HDT. <i>5, 1 ; 6, 105, etc. ; ao. pass</i>. ἐϐώσθην, HDT. <i>6, 131 ; 8, 124 ; pf. part</i>. βεϐωμένα, HDT. <i>3, 39 ; ao. moy. 3 sg</i>. ἐϐώσατο, THCR. <i>Idyl. 17, 60. Formes dor. avec rad. en</i> βοᾱ- (<i>au lieu de</i> βοη-) : <i>fut</i>. βοάσομαι, AR. <i>Nub. 1154 ;</i> PHRYN. COM. <i>2-1, 598 Mein. ;</i> ANTH. <i>App. 200 ; rar</i>. βοάσω, EUR. <i>Ion 1446. Ao. 3 sg</i>. ἐϐόασε, EUR. <i>Tr. 522 ; ou sans augm</i>. βόασε, PD. <i>P. 6, 36 ;</i> EUR. <i>Andr. 298 ; inf</i>. βοᾶσαι, ÆSION (ARSTT. <i>Rhet. 3, 10, 7) ; part</i>. βοάσαις, PD. <i>O. 8, 40. Pf. pass</i>. βεϐόαμαι, ANTH. <i>15, 4</i>.<br><span><b>Étym</b>. βοή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοαω - βοάω</font>\n<br><br>apparemment forme d'un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – crier, comme manifestation de sentiment, de détresse\n<br><br> – crier, appeler pour un motif, dans un but\n<br><br> – crier avec rudesse, souvent avec un son inarticulé et brutal\n<br><br> – intensif de , crier grossièrement, avec mépris, etc.\n<br><br> suggère l'intelligence ;  la sensibilité ;  les instincts</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G995":"<h1>boe</h1>\n<p>Strong n° 995 <i>Prononciation [bo-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un cri</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βοή, ῆς (ἡ) :<br>A</b> cri, <i>d’où :</i><br><b>   I</b> cri de l’homme et des animaux :<br><b>      1</b> cri de l’homme, <i>part</i>. cri d’appel, OD. <i>9, 401 ; 10, 118, etc. ;</i> cri de douleur, IL. <i>6, 465 ;</i> OD. <i>14, 266 ; 24, 48 ;</i> cri de joie, <i>d’où</i> joie bruyante, vive allégresse, AR. <i>Pl. 637 ;</i> EUB. <i>3, 249 Meineke</i> cri de guerre (<i>sel. d’autres,</i> bruit <i>ou</i> tumulte du combat) IL. <i>11, 50 ; 14, 4, etc. ;</i> OD. <i>22, 77, etc. ; d’où</i> βοὴν ἀγαθός, IL. <i>2, 408, etc</i>. vaillant pour pousser le cri de guerre ; <i>en parl. d’une foule,</i> cri confus, PLAT. <i>Leg. 700</i> e, <i>792</i> a ; <i>joint à</i> θόρυϐος, PLAT. <i>Tim. 70</i> e ; βοὴν βοᾶν (<i>v</i>. βοάω), <i>ou</i> θωΰσσειν, SOPH. <i>Aj. 335 ;</i> ἀϋτεῖν, EUR. <i>Hec. 1092 ;</i> κελαδεῖν, EUR. <i>Hel. 371 ; etc</i>. pousser un cri ;<br><b>      2</b> cri des animaux, EUR. <i>Bacch. 1085 ;</i> cri <i>ou</i> chant des oiseaux, SOPH. <i>Ant. 1021 ;</i><br><b>   II</b> <i>p. anal</i>. son bruyant (d’un instrument) : bruit de la trompette, ESCHL. <i>Sept. 394 ;</i> son aigu de la flûte, IL. <i>18, 495 ;</i> PD. <i>O. 3, 8 ; N. 5, 38 ; etc</i>. son de la lyre, PD. <i>P. 10, 39 ; d’où</i> musique, <i>en gén</i>. PD. <i>P. 1, 13 ;</i><br><b>   III</b> <i>p. ext</i>. toute parole sonore, <i>d’où :</i><br><b>      1</b> chant, PD. <i>N. 3, 67 ;</i> EUR. <i>El. 872 ;</i> AR. <i>Ran. 212 ;</i><br><b>      2</b> parole, <i>en gén. en parl. d’une réponse d’oracle,</i> EUR. <i>Ion 92 ; de prières de suppliants,</i> ESCHL. <i>Pers. 936, etc. ; d’invocations,</i> EUR. <i>Ph. 1036 ; de paroles en gén. :</i> ὅσον ἀπὸ βοῆς ἕνεκα (<i>ou</i> ἕνεκεν) THC. <i>8, 92 ;</i> XÉN. <i>Hell. 2, 4, 31, ou simpl</i>. ὅσον ἀπὸ βοῆς, DC. seulement pour parler, <i>càd</i>. par feinte <i>ou</i> en apparence ;<br><b>B</b> secours, <i>c</i>. βοήθεια, ESCHL. <i>Suppl. 730 ; Ag. 1349</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. βοά, PD. <i>ll. cc. ;</i> THCR. <i>Idyl. 16, 97</i>.<br><span><b>Étym</b>. <i>onomatopée</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοη - βοή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G996":"<h1>boetheia</h1>\n<p>Strong n° 996 <i>Prononciation [bo-ay'-thi-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aide, secours</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βοήθεια, ας (ἡ) :<br>      1</b> secours : ὑπέρ τινος, DÉM. <i>1287, 27,</i> en faveur de qqe ch. ; τινι, pour qqe ch. PLAT. <i>Parm. 128</i> c, <i>ou</i> contre qqe ch. XÉN. <i>Mem. 2, 8, 6 ; au plur</i>. ARSTT. <i>Rhet. 2, 5, 17 ; part</i>. secours médical, soins de médecin, PLUT. <i>Alex. 19 ;</i><br><b>      2</b> <i>p. suite,</i> expédition de secours, troupe de secours, troupe auxiliaire, THC. <i>4, 8 ; p. opp. aux forces régulières,</i> DÉM. <i>49, 1</i>.<br><span><b>Étym</b>. βοηθέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοηθεια - βοήθεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G997":"<h1>boetheo</h1>\n<p>Strong n° 997 <i>Prononciation [bo-ay-theh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aider, secourir, apporter une aide</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βοη·θέω-ῶ</b> <span>(<i>impf</i>. ἐϐοήθουν, <i>f</i>. βοηθήσω, <i>ao</i>. ἐϐοήθησα, <i>pf</i>. βεϐοήθηκα ; <i>pass. pf</i>. βεϐοήθημαι)</span> <i>litt</i>. courir au secours, <i>d’où</i> venir au secours de, <i>en parl. d’un secours de guerre (en hommes, en vaisseaux, etc</i>.) : ἐς <i>ou</i> ἐπὶ τόπον, HDT. <i>6, 103 ; 4, 125 ;</i> THC. XÉN. venir au secours d’une place, d’un pays, <i>etc. ;</i> β. τινι, HDT. <i>1, 82 ;</i> EUR. <i>I.A. 79 ;</i> πρός τινα, XÉN. <i>Hell. 1, 2, 3,</i> venir au secours de qqn ; τινι ἀντία τινός, HDT. <i>5, 99, ou</i> τινι πρός τι, XÉN. <i>Hell. 4, 8, 38,</i> secourir qqn contre un ennemi, contre un danger ; ναυσὶ β. τινι, XÉN. <i>Hell. 1, 6, 22,</i> venir avec sa flotte au secours de qqn ; <i>p. anal. en parl. d’un secours <i>ou</i> d’une aide quelconque :</i> β. χρήμασι, ARSTT. <i>Nic. 5, 2, 2,</i> aider de sa bourse, β. τινι τὰ δίκαια, XÉN. <i>Mem. 2, 6, 25,</i> aider qqn à faire prévaloir son droit ; β. τοῖς νόμοις, ESCHN. <i>5, 23, etc</i>. venir au secours des lois ; <i>en parl. d’un médecin,</i> donner ses soins (à un malade), PLUT. <i>Alex. 19. ; en parl. d’un remède,</i> être bon contre, <i>dat</i>. DIOSC. <i>1, 6 ; impers</i>. βοηθεῖ πρός τι, TH. <i>H.P. 9, 20, 1,</i> cela vient en aide pour qqe ch. ; <i>au pass</i>. être secouru, recevoir du secours, de l’aide, DIOSC. <i>4, 83 ;</i> PLUT. <i>M. 687</i> f, <i>689</i> b, <i>720</i> c ; παρά τινος, ARSTT. <i>Rhet. 2, 6,</i> de qqn ; <i>impers</i>. ἐμοὶ βεϐοήθηται, ANT. <i>114, 36,</i> on est venu à mon secours ; <i>cf</i>. PLAT. <i>Ep. 347</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. réc</i>. ἐϐοηθήθην, SPT. <i>Esaï. 10, 3 ; 30, 2. Fut. moy</i>. βοηθήσομαι <i>au sens pass</i>. SPT. <i>Dan. 11, 34. — Par contract. ion</i>. βωθ- <i>au lieu de</i> βοηθ- : <i>prés. impér. 2 pl</i>. βωθεῖτε, ANTH. <i>12, 84 ; mais impf</i>. ἐϐοήθεον (<i>sel. Dind</i>. ἐϐώθεον), HDT. <i>6, 103, 108, 138 ; ao</i>. ἐϐοήθησα (ἐϐώθησα <i>Dindorf</i>), HDT. <i>7, 165 ; dans Hpc. touj</i>. βοηθέω, — <i>Dans une inscr. att. part. ao. plur</i>. βοιηθήσαντες, CIA. <i>2, 121, 24 (338 av. J.C</i>.).<br><span><b>Étym</b>. βοή, θέω ; <i>cf</i>. βοηδρομέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοηθεω - βοηθέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Actes (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G998":"<h1>boethos</h1>\n<p>Strong n° 998 <i>Prononciation [bo-ay-thos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui aide, qui apporte secours, appui</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βοηθός, ός, όν</b>, qui vient au secours de, HDT. <i>5, 77, 97 ;</i> THC. <i>1, 45 ;</i> ὁ β. auxiliaire de, défenseur de, <i>dat</i>. XÉN. <i>Cyr. 5, 3, 19 ;</i> ANT. <i>111, 40</i>.<br><span><b>Étym</b>. <i>cf</i>. βοηθόος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοηθος - βοηθός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G999":"<h1>bothunos</h1>\n<p>Strong n° 999 <i>Prononciation [both'-oo-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une fosse, un fossé, trou dans le sol</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βόθυνος, ου (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> <i>c</i>. βόθρος CRAT. (<i>Bkk. 85</i>) ; XÉN. <i>Œc. 19, 3 ; etc. ;</i><br><b>      2</b> <i>au plur</i>. sorte de météores ; ARSTT. <i>Meteor. 1, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοθυνος - βόθυνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>"};
